quests[8429] = { id = 8429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle of Warsong Gulch", description = "The battle in Warsong Gulch against the Silverwing Sentinels is of great importance.  Under the guise of protecting a forest that doesn't belong to them, the Alliance seeks to deny the Horde one of our largest sources for lumber.\n\nDo not let this happen, {name}!  Come back to me with proof of serving the Horde in a worthy manner!", sourceObjective = "Bring 3 Warsong Gulch Marks of Honor to a Horde Warbringer outside the battlegrounds.", progress = "Do you bear news from Warsong Gulch, {name}?", completion = "Excellent!  You've shown your worth by defending our operations in Warsong Gulch!  May word of your honor spread far and wide across our lands.", sourceObjectiveStatus = "unverified-source-field" }
quests[8430] = { id = 8430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle of Warsong Gulch", description = "The battle in Warsong Gulch against the Silverwing Sentinels is of great importance.  Under the guise of protecting a forest that doesn't belong to them, the Alliance seeks to deny the Horde one of our largest sources for lumber.\n\nDo not let this happen, {name}!  Come back to me with proof of serving the Horde in a worthy manner!", sourceObjective = "Bring 3 Warsong Gulch Marks of Honor to a Horde Warbringer outside the battlegrounds.", progress = "Do you bear news from Warsong Gulch, {name}?", completion = "Excellent!  You've shown your worth by defending our operations in Warsong Gulch!  May word of your honor spread far and wide across our lands.", sourceObjectiveStatus = "unverified-source-field" }
quests[8431] = { id = 8431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle of Warsong Gulch", progress = "The battle in Warsong Gulch rages on, {name}.  Do your part to drive the Silverwing Sentinels out of our lands!", completion = "Well done, {class}!  You've helped ensure the Horde's ownership over Warsong Gulch!" }
