quests[8435] = { id = 8435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle of Warsong Gulch", progress = "The battle in Warsong Gulch rages on, {name}.  Do your part to drive the Silverwing Sentinels out of our lands!", completion = "Well done, {class}!  You've helped ensure the Horde's ownership over Warsong Gulch!" }
quests[8436] = { id = 8436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conquering Arathi Basin", description = "Our conflict with the Alliance has escalated to a true war.  No longer are false pretenses to enter into battle used or expected by either side at this point.\n\nThe battle for the Arathi Basin is one of resources, plain and simple.  Either the Alliance gets the resources and uses them against us or we get them and use them to keep our war efforts going.  Help the Defilers maintain the flow of resources we need, {name}!", sourceObjective = "Bring 3 Arathi Basin Mark of Honor to a Horde Warbringer outside the battlegrounds.", progress = "You've come back with news from Arathi, {class}?", completion = "Securing our resources in Arathi is an important task!  You've done well, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8437] = { id = 8437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conquering Arathi Basin", description = "Our conflict with the Alliance has escalated to a true war.  No longer are false pretenses to enter into battle used or expected by either side at this point.\n\nThe battle for the Arathi Basin is one of resources, plain and simple.  Either the Alliance gets the resources and uses them against us or we get them and use them to keep our war efforts going.  Help the Defilers maintain the flow of resources we need, {name}!", sourceObjective = "Bring 3 Arathi Basin Mark of Honor to a Horde Warbringer outside the battlegrounds.", progress = "You've come back with news from Arathi, {class}?", completion = "Securing our resources in Arathi is an important task!  You've done well, {name}.", sourceObjectiveStatus = "unverified-source-field" }
