quests[8446] = { id = 8446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shrouded in Nightmare", description = "Corruption seeps from this object.\n\nThere may be a link between this object and the dragons coming forth from the Dream. You must find someone that can decipher the meaning of this item. Perhaps the druids of the Moonglade or Cenarion Hold could assist you further.", sourceObjective = "Find someone capable of deciphering the meaning behind the Nightmare Engulfed Object.\n\nPerhaps a druid of great power could assist you.", progress = "Yes, {race}?", completion = "I must remove the taint from this object. This may shed some light on my recent failures to delve into the Dream. Give it to me.", sourceObjectiveStatus = "unverified-source-field" }
quests[8447] = { id = 8447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waking Legends", description = "The waters of Lake Elune'ara should dissolve the nightmares engulfing this object. Give me a moment to perform the cleansing, {name}.", sourceObjective = "Wait for Keeper Remulos at the Moonglade to cleanse the Nightmare Engulfed Object.", progress = "You have seen that which you must.", completion = "Take his ring, {name}. It has served its purpose for Malfurion. It shall now serve a new purpose for you...", sourceObjectiveStatus = "unverified-source-field" }
quests[8460] = { id = 8460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "imbermaw Ally", description = "The Timbermaw are the only furbolg tribe to escape the corruption. However, many other races kill furbolg blindly now, without bothering to see if they are friend or foe. For this reason, the Timbermaw furbolg trust very few.\n\nAre you interested in proving yourself? Drive back the corrupted Deadwood tribe of Felwood and we may one day consider you an ally. You'll find the first Deadwood tribe - warriors, pathfinders and gardeners - to my west.", sourceObjective = "Grazle wants you to prove yourself by killing 6 Deadwood Warriors, 6 Deadwood Pathfinders, and 6 Deadwood Gardeners. Return to him in southern Felwood near the Emerald Sanctuary when you are done.", progress = "Keep at it, {name}.  If you are to earn our trust, you will need to prove yourself to us.", completion = "We suffer much from the events of the past.  Thank you for what you have done to help protect the Timbermaw.  As a sign of our growing friendship, please accept this humble offering.", sourceObjectiveStatus = "unverified-source-field" }
quests[8461] = { id = 8461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "eadwood of the North", description = "There is a camp of Deadwood furbolgs directly to our southwest.  Corruption permeates the camp, and I wish to put an end to it before they become a problem.\n\nThe Deadwood tribe is evil, but it is the effects of the fel that pollutes their minds.  Their hostility is not truly an innate quality, yet they cannot be helped.  It saddens me that we must fight our own brethren.\n\nPlease, {name} - I ask you to do what must be done.  Simply spare me the details; such troublesome images upset me far too much.", sourceObjective = "Nafien would like you to kill 6 Deadwood Den Watchers, 6 Deadwood Avengers, and 6 Deadwood Shamans. Return to him in northern Felwood near the entrance to Timbermaw Hold.", progress = "Once you gain the trust of the Timbermaw, I am confident there will be something we will be able to do for you.  The Timbermaw do not forget their allies, especially in dark times such as these.", completion = "I sense that you have achieved victory.  Victory... such a hollow word considering what had to be done.  Regardless, you've proven yourself to be worthy of our trust.\n\nIt may take some time before the Timbermaw welcome you without hostility within the Hold.  Still, your perseverance will erode any suspicion my brethren may have about you.  So long as you never betray us and raise weapons against us, we will find common ground.", sourceObjectiveStatus = "unverified-source-field" }
quests[8462] = { id = 8462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "peak to Nafien", description = "Perhaps you are capable of handling a larger threat that we Timbermaw face.  You certainly have shown yourself capable here...\n\nAnother of my kind stands guard outside the entrance to Timbermaw Hold, along this road far to the north.  His name is Nafien; while he may appear to be a feral and unsavory beast, fear him not.  He only seeks aid against the malign forces that threaten our home.", sourceObjective = "Travel north along the main road in Felwood and speak with the furbolg named Nafien. He stands guard outside the entrance to Timbermaw Hold.", completion = "Ah... I have heard the word on the wind about those not of our tribe who seek to ally themselves with the Timbermaw furbolgs.  I welcome you, but you must be warned that my tribe reacts poorly to strangers.\n\nThese are trying times, and we can only trust those who choose to fight the corruption of the land along side of us... and have proven themselves to us accordingly.  Those who have not done so will be met with open hostility should they enter the Hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[8463] = { id = 8463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unstable Mana Crystals", description = "A group of Wretched recently raided a supply of unstable mana crystals from one of our arcane sanctums.  If not handled properly, the crystals could explode with enough force to blow a hole into the city walls.\n\nNow, {name}, I don't quite care if they blow themselves up while tapping unstable arcane sources, but the whole incident would make my men look bad.\n\nBring me back any remaining stolen crystals you find; they might still be inside their original crates.", sourceObjective = "Bring back 6 Unstable Mana Crystals to Aeldon Sunbrand at Falconwing Square.", progress = "Did you retrieve the stolen goods yet?", completion = "Excellent work, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8464] = { id = 8464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "interfall Activity", description = "The Timbermaw tend to stay to themselves, {name}.  While we do allow safe passage to those we trust, we try to avoid other furbolg tribes if at all possible.\n\nThe Winterfall tribe as of late has become increasingly hostile towards us.  They seem to be in a state of rage, completely engulfed by their own fear and hatred of anything they do not understand.\n\nI must ask you to thin their numbers as to lessen the threat against us.  Seek them out in Winterfall Village, far to the east of here.", sourceObjective = "Salfa wants you to kill 8 Winterfall Shaman, 8 Winterfall Den Watchers, and 8 Winterfall Ursa. Salfa is located just outside the entrance to Timbermaw Hold in Winterspring.", progress = "We very much appreciate what you have done for the Timbermaw, {name}.  Your continued efforts will surely earn my tribe's trust and respect.", completion = "Thank you for what you have done, as saddening as it is.  Accept this as a token of thanks.\n\nI would ask of you to please continue helping us, {name}.  We have very few allies on which to call upon, and without your aid, the threats against my tribe would surely be too much for us to handle alone.", sourceObjectiveStatus = "unverified-source-field" }
quests[8465] = { id = 8465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "peak to Salfa", description = "The threat of corruption comes not only from the Deadwood furbolgs to the south, but also from the east and the Winterfall furbolgs of Winterspring.  If you wish to further aid us, speak with Salfa on the other side of the Hold, by the Winterspring entrance.  Follow the path to the left to reach it.\n\nBe warned - if my kind inside considers you hostile or hated, they will attack.  Travel as quick as you can, avoiding conflict.  To kill a Timbermaw - even in self defense - will only alienate you further.", sourceObjective = "Travel through Timbermaw Hold and exit into Winterspring. Speak with Salfa, who stands guard outside the entrance to Timbermaw Hold.", completion = "Greetings, {class} - I stand guard here as both a speaker for the Timbermaw here in Winterspring and as a defender of the tribe.\n\nOur Winterfall brethren here in this frigid land have fallen under the same corruptive sway as the furbolg of Felwood.  If you've come here offering the Timbermaw furbolgs aid, then we are ready to accept such an offer.", sourceObjectiveStatus = "unverified-source-field" }
quests[8466] = { id = 8466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feathers for Grazle", progress = "While you have proven yourself to me, you may need to continue to work toward proving yourself to the suspicious brethren of my tribe.  To that end, I may be able to continue assisting you.\n\nSome of the Deadwood furbolgs wear a distinctive headdress that may be used as a means of proof in thinning their numbers.  Bring me a feather from any headdresses you acquire; for every set of five you bring me, you will earn recognition amongst the Timbermaw.", completion = "Well done, {name}!  I will make sure that your deeds are known amongst my kind.\n\nRemember to bring any of the feathers you find to me.  I will continue to accept them as long as necessary." }
quests[8467] = { id = 8467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feathers for Nafien", progress = "While you have proven yourself to me, you may need to continue to work toward proving yourself to the suspicious brethren of my tribe.  To that end, I may be able to continue assisting you.\n\nSome of the Deadwood furbolgs wear a distinctive headdress that may be used as a means of proof in thinning their numbers.  Bring me a feather from any headdresses you acquire; for every set of five you bring me, you will earn recognition amongst the Timbermaw.", completion = "Well done, {name}!  I will make sure that your deeds are known amongst my kind.\n\nRemember to bring any of the feathers you find to me.  I will continue to accept them as long as necessary." }
quests[8468] = { id = 8468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Thaelis the Hungerer", description = "The city of Silvermoon hereby issues a reward for the head of Thaelis the Hungerer, notorious Wretched ringleader.  He is wanted for repeated crimes against the general populace of Silvermoon City, including the murder of two city guards.\n\nReport to Sergeant Kan'ren to collect the reward.", sourceObjective = "Bring Thaelis's Head to Sergeant Kan'ren at Falconwing Square in Eversong Woods.", progress = "You have something to show me?", completion = "That scoundrel, Thaelis, finally met his fate.  Good job, {name}.  Things should be quiet with the Wretched for a while.", sourceObjectiveStatus = "unverified-source-field" }
quests[8469] = { id = 8469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beads for Salfa", progress = "You've certainly earned my trust, {name}, but you may need to continue to earn the trust of my untrusting tribe.  There is something you can do to earn that trust.\n\nThe Winterfall are known to carry spirit beads to ward against foul spirits.  These beads have clearly failed in their purpose, as the Winterfall themselves are the agents of corruption.  Bring to me these spirit beads from fallen Winterfall furbolgs; for every set of five you bring me, you will earn recognition amongst the Timbermaw.", completion = "Once again, you prove your honor to us!  I will make sure that your deeds are known amongst my kind.\n\nRemember to bring any of the Winterfall's beads you find to me.  For each set you continue to bring to me, I will speak on your behalf to the tribe." }
quests[8470] = { id = 8470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deadwood Ritual Totem", description = "You have found one of the Deadwood furbolg's ritual totems.  The totem itself is of non-descript construction, but a palpable sense of despair emanates from it.  If there were any object that might best exemplify the corruption that the Deadwood furbolg suffer under, this item would clearly be it.\n\nOne of the furbolgs inside Timbermaw Hold may have a use for such an item... that is, if you've earned their trust enough for them to speak with you.", sourceObjective = "Take the Deadwood Ritual Totem inside Timbermaw Hold and see if one of the furbolgs there will find a use for the item. The Timbermaw will not speak with you unless you are of Neutral reputation or greater with them.", progress = "Yes {class}, what can I assist you with?  You walk among us peacefully, though there is assuredly something amiss.  I sense something... something troubling...", completion = "This totem... I recognize it as one of the Deadwood's, but it is thick with the stench of decay.  Whatever foulness has turned our brethren against us is surely present in this object.\n\nYou were wise to bring this to us, {name}.  Perhaps through study and ritual, we can uncover what it is that pollutes the minds of our brethren.  Thank you, friend - please accept these offerings in exchange for your find.", sourceObjectiveStatus = "unverified-source-field" }
quests[8471] = { id = 8471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterfall Ritual Totem", description = "You have found one of the Winterfall furbolg's ritual totems.  The totem itself is of non-descript construction, but it seems to emanate an almost tangible sense of dread and despair.  If many of the Winterfall furbolgs do indeed carry these, it certainly would go a long way in explaining their current condition.\n\nOne of the furbolgs inside Timbermaw Hold may have a use for such an item... that is, if you've earned their trust enough for them to speak with you.", sourceObjective = "Take the Winterfall Ritual Totem inside Timbermaw Hold and see if one of the furbolgs there will find a use for the item. The Timbermaw will not speak with you unless you are of Neutral reputation or greater with them.", progress = "{class} - you approach us in a peaceful manner, but I sense that you are here on matters that are grave and severe... for both furbolg and {race} alike.  What have you come to tell us?", completion = "This thing... it is in the shape of a Winterfall Ritual Totem, but it has been twisted by forces I cannot begin to comprehend.  Whatever taint that has set the Winterfall against us is surely present in this object.\n\nDivine wisdom has brought both this and you to us, {name}.  We will study this object intently; perhaps one day, the Winterfall will rage against us no longer.\n\nThank you, friend - please accept these offerings in exchange for your benevolence.", sourceObjectiveStatus = "unverified-source-field" }
quests[8472] = { id = 8472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Major Malfunction", description = "The arcane patrollers crafted by our forefathers to protect the city have fallen into a dangerous state of disrepair.  They fail to recognize us as their masters and will attack us on sight!\n\nEven though they were created many years ago, the arcane cores that power them are still quite useful and valuable to us.  I want you to gather these cores and bring them to me so I can put them to good use again.  You will find the patrollers in the ruined section of Silvermoon, to the northwest.", sourceObjective = "Collect 6 Arcane Cores from the Arcane Patrollers that roam the ruins of Silvermoon City and bring them to Magister Jaronis at Falconwing Square in Eversong Woods.", progress = "Have you succeeded in gathering the arcane cores yet, {name}?", completion = "You've done well, {name}.  With our arcane sanctums not operating at full capacity, these power cores will go a long way in supplementing our needs.", sourceObjectiveStatus = "unverified-source-field" }
quests[8473] = { id = 8473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Somber Task", description = "These are difficult times for us, {name}.  It was a very hard decision to burn the woods bordering the Ghostlands to prevent the Scourge's expansion.\n\nThe treants, who have been our friends for years, are now trying to foster the regrowth of the forest along the Scorched Grove.\n\nThis is a painful thing to ask of you, {class}, but we've failed to convince our former allies to cease their endeavors.  I need you to stop them by the only means that remain to us: force.", sourceObjective = "Slay 10 Withered Green Keepers at the Scorched Grove. Then report back to Larianna Riverwind inside the tower just to the northwest of the Scorched Grove in Eversong Woods.", progress = "I dread to ask, {name}... is the task done?", completion = "So, it is done.  Curse these times that have driven us to desperate measures... and curse our enemy, the Scourge!\n\nLearn this, {name}.  Our lands must be protected, no matter what the cost.  We shall prevail!", sourceObjectiveStatus = "unverified-source-field" }
quests[8475] = { id = 8475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dead Scar", description = "The black swath of soil that cuts through Eversong Woods is a permanent reminder of the day Arthas led the Scourge into our beloved city.\n\nThis blemish is more than an eyesore as even today it brings Scourge from the Ghostlands to Silvermoon.\n\nGo, {name}, and give my men a hand in killing the mindless undead that walk down the Dead Scar.", sourceObjective = "Slay 8 Plaguebone Pillagers and report back to Ranger Jaela on the Dead Scar in Eversong Woods.", progress = "You're back, {name}.  Did you fight off the undead along the Dead Scar yet?", completion = "We don't anticipate the Scourge letting up on their attacks any time soon, but we still appreciate any help we get guarding the Scar.", sourceObjectiveStatus = "unverified-source-field" }
quests[8476] = { id = 8476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amani Encroachment", description = "Ours are not the vast kingdoms of the humans and orcs.  All we have left of our lands in Azeroth lies mostly before your eyes, {name}.\n\nUntil we can reach Outland, we must defend what little land we have at any cost.\n\nOur uncivilized neighbors to the southeast, the Amani trolls, certainly have a different opinion regarding the ownership of these lands.  Their daily raids are something we can't tolerate anymore.  Go to their settlements, Zeb'Watha and Tor'Watha, and teach them a lesson.", sourceObjective = "Lieutenant Dawnrunner at the Farstrider Retreat in Eversong Woods wants you to kill 5 Amani Berserkers and 5 Amani Axe Throwers.", completion = "Good work, {name}.  With more people like you we'll soon restore our lands to their former glory.", sourceObjectiveStatus = "unverified-source-field" }
quests[8477] = { id = 8477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spearcrafter's Hammer", description = "The Amani and the sin'dorei have a long history of mutual dislike and open hostility.  That doesn't prevent me from appreciating a fellow craftsman's work, {name}.\n\nI've come across pieces of Amani weaponry and I must admit I'm impressed by the quality of their work.  It is rumored that Spearcrafter Otembe wields a magical hammer that is so light and well-balanced it allows him to work with great dexterity and efficiency.\n\nIf you bring me this tool I'll use it to craft you a weapon.", sourceObjective = "Search Tor'Watha to the southeast of the Farstrider Retreat for Spearcrafter Otembe and bring Otembe's Hammer to Arathel Sunforge at the Farstrider Retreat in Eversong Woods.", progress = "You've brought me Otembe's hammer, {name}?", completion = "There's truth to the rumors, {name}.  This hammer is light and strong at once; I shall manage to complete several of my unfinished projects.  And of course, I'll let you have first pick.", sourceObjectiveStatus = "unverified-source-field" }
quests[8479] = { id = 8479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zul'Marosh", description = "Come closer, mon.  Don't be 'fraid, Ven'jashi not gonna hurt you.\n\nUs Darkspears be mortal enemies of the Amani just like you.  Their boss Zul'Marosh is evil troll.  He give me the bad poison and leave me in this cage to die.\n\nI not scared of dyin', mon.  I seen death in the eye an' I laugh at her.\n\nI cannot die in peace yet, mon.  Not 'til Zul'Marosh be dead too.  You find him 'cross the lake in Zeb'Watha.  I hold this poison off 'til you bring me his big ugly head, mon.  Only then I die peacefully.", sourceObjective = "Ven'jashi, the troll prisoner at Tor'Watha, wants you to bring him Chieftain Zul'Marosh's Head. Chieftain Zul'Marosh can be found in Zeb'Watha, across Lake Elrendar.", progress = "You bring me Zul'Marosh's head?", completion = "Ya, mon.  Zul'Marosh had this comin'.  He burn down Ven'jashi's village.  I kill many Amani before they put me in this cage.  I hide something in the sand, my gift for you now.\n\nAh... ah, the poison... it spread now, mon.  Time to rest...", sourceObjectiveStatus = "unverified-source-field" }
quests[8480] = { id = 8480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Armaments", description = "The Wretched grow bolder every day, {name}.  They've achieved enough coordination to launch an attack on Sunsail Anchorage.\n\nAs if that weren't embarrassing enough, most of our weapons were left behind when they attacked.  Bring me back our armaments so that we may show those ruffians who's boss.", sourceObjective = "Bring 8 Sin'dorei Armaments to Velendris Whitemorn in Eversong Woods.", progress = "Did you gather the lost weapons yet?", completion = "Great job, {name}.  Let's show the Wretched what we're made of!", sourceObjectiveStatus = "unverified-source-field" }
quests[8481] = { id = 8481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Root of All Evil", description = "{name}, thanks to you we have devised a way to summon forth the root of all evil for the Winterfall tribe - the corrupting demon that dominates them!\n\nTake this torch to the mouth of Grolnar's personal cave and plant it there.  Doing so will force the demon to reveal itself and investigate.  This is when you and your allies must strike it down!  Only the essence of the fallen demon will begin the lengthy healing process of the Winterfall tribe... and the salvation of Timbermaw Hold.", sourceObjective = "Plant the Demon Summoning Torch in the mouth of Grolnar's cave in the Winterfall furbolg village. Defeat the demon and retrieve the Essence of Xandivious for Gorn One Eye in Timbermaw Hold.", progress = "You have returned to us, {name}... does this mean that the demon has been slain?", completion = "You've... you've saved us!  Your defeat of the demon Xandivious has ensured the safety of Timbermaw Hold for years to come.  You are truly a hero amongst our kind.\n\nPlease, accept this with our blessing.  Though the healing process will be slow amongst the furbolgs - and the conflict will still go on - you have given the Winterfall something they never had before this day.\n\nThey have a chance at survival.", sourceObjectiveStatus = "unverified-source-field" }
quests[8482] = { id = 8482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Incriminating Documents", description = "The documents contain detailed maps of different strategic buildings in Eversong Woods.  A diagram of an arcane sanctum is also sketched in good detail.  There seem to be numerous notes in a language you don't recognize.\n\nAs these were carried by a Darnassian spy, it might be a good idea to bring them to the Captain of the Guard - Aeldon Sunbrand.", sourceObjective = "Bring the Incriminating Documents to Aeldon Sunbrand at Falconwing Square in Eversong Woods.", progress = "You've got something for me?  Let me take a look.", completion = "Are you sure you found these on a night elf?  They're clearly written in Dwarven...\n\nFrom what I can understand of this letter, whoever wrote this did not cause the malfunction, but rather was sent here as a spy to observe the results of it.  They call our endeavors reckless and dangerous... but who?\n\nOf course!  That envoy from Ironforge!  We were fools to trust anyone belonging to the Alliance!", sourceObjectiveStatus = "unverified-source-field" }
quests[8483] = { id = 8483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dwarven Spy", description = "Listen, {name}.  This is a very delicate situation; even though we've identified the spy, we cannot kill him out in the open.  We cannot try to capture him either as the risk of him escaping is too great.\n\nI want you to go find Prospector Anvilward at the North Sanctum and kill him.  Do this in a quiet manner, we don't want word to spread that we allowed a spy into our city.\n\nBring me his head as proof.  Ironforge will learn not to meddle with the sin'dorei.", sourceObjective = "Bring Prospector Anvilward's Head to Aeldon Sunbrand at Falconwing Square in Eversong Woods.", progress = "Did you take care of the intruder?", completion = "So, the deed is done.  Excellent job.\n\nWord has been passed to the ranger general and believe me, the dwarves will pay dearly for their treason.\n\nYou've been of great service to your people today, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8484] = { id = 8484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brokering of Peace", description = "Your deeds go beyond the tale of a simple hero, {name}.  If you are a representative of your people, then your people are ones we would work to make peace with.\n\nPlease - take this offering to the dwarven king that resides in a mountain of iron; I believe you call this city Ironforge.  In times past, he had tried to make contact with us on behalf of his Alliance.  It is now only fitting to acknowledge you as the key in your Alliance's efforts in brokering peace.", sourceObjective = "Bring the Timbermaw Offering of Peace to King Magni Bronzebeard in Ironforge.", progress = "{class}, you are welcomed in my domain.  Ironforge should always be considered a home to a hero such as yourself.  Now, what business do you have with me?", completion = "Indeed, this is a most fortuitous turn of events.  Were a lasting peace to be made with these creatures, this would certainly give us an advantage in the affairs of Kalimdor... one that the Night Elves cannot support on their own.  I will notify the other leaders of the Alliance of this immediately, and further diplomats will be dispatched!\n\nAs for you, {name}... you have shown courage in both diplomacy and in action.  I thank you, as does the whole of the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[8485] = { id = 8485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brokering of Peace", description = "Your deeds go beyond the tale of a simple hero, {name}.  If you are a representative of your people, then your people are ones we would work to make peace with.\n\nPlease - take this offering to the orcish warchief that resides in the lands of Durotar; I believe you call this city Orgrimmar.  In times past, he had tried to make contact with us on behalf of his Horde.  It is now only fitting to acknowledge you as the key in your Horde's efforts in brokering peace.", sourceObjective = "Bring the Timbermaw Offering of Peace to Shok Narnes in Orgrimmar.", progress = "The warchief's greetings are bestowed upon you, {class}.  Your deeds make the Horde grow stronger in these troubling times.  Now, what business do you have with me?", completion = "Indeed, this is a most fortuitous turn of events.  Were a lasting peace to be made with these creatures, this would certainly give us an advantage in securing Kalimdor from external threats.  I will notify the other leaders of the Horde of this immediately, and further diplomats will be dispatched!\n\nAs for you, {name}... you have shown courage in both diplomacy and in action.  I thank you, as does the entirety of the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[8486] = { id = 8486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Instability", description = "It's about time that dimwit, Caidanis, sent someone this way.\n\nI warned of the dangers of increasing the load on the West Sanctum!  Now one of our energy converters is destroyed and arcane wraiths are pouring out of the sanctum!\n\nI'm going to need you to take care of these creatures before we send anyone in for repairs.  Make haste!", sourceObjective = "Ley-Keeper Velania wants you to kill 5 Manawraiths and 5 Mana Stalkers.", progress = "Did you take care of the arcane wraiths?", completion = "Thank you, {name}.  Now that we have the wraiths under control we can send someone in to assess the damage.  Hopefully this wasn't anything permanent.", sourceObjectiveStatus = "unverified-source-field" }
quests[8487] = { id = 8487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Soil", description = "This was a fully functional arcane sanctum before Arthas and his army of Scourge decided to plow through it on their way to Silvermoon.\n\nNow it's as useful to us as any part of the Dead Scar.  The soil is tainted, undead are drawn to it and the energy in the ley lines is completely disrupted.\n\nWhat I want to know, {name}, is whether this taint is reversible or not.  I want you to collect soil samples from this area so I can study them.  Perhaps with time we can set things back to normal.", sourceObjective = "Apprentice Mirveda at the East Sanctum in Eversong Woods wants you to collect 8 Tainted Soil Samples.", progress = "Are you done collecting the samples I asked for, {name}?", completion = "Excellent.  I will cast an augmentation enchantment on the samples so I can more clearly analyze the taint on the soil.", sourceObjectiveStatus = "unverified-source-field" }
quests[8488] = { id = 8488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unexpected Results", description = "Something's wrong, {name}.  I sense the presence of Scourge.  Be ready to fight them!", sourceObjective = "Protect Apprentice Mirveda from the Scourge ambush.", progress = "Is it over?  Are they all gone?", completion = "My endeavors are hopeless, {name}.  The very nature of the soil has been altered... the taint is irreversible.  Thank you for your assistance.  I'll need to ask one last task of you.", sourceObjectiveStatus = "unverified-source-field" }
quests[8489] = { id = 8489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Intact Converter", description = "This object appears to be one of the arcane converters Ley-Keeper Velania mentioned.  It hasn't been damaged by the fire, perhaps she could find a use for it.", sourceObjective = "Bring the Intact Arcane Converter to Ley-Keeper Velania.This object appears to be one of the arcane converters Ley-Keeper Velania mentioned. It hasn't been damaged by the fire, perhaps she could find a use for it.", sourceObjectiveStatus = "unverified-source-field" }
quests[8490] = { id = 8490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Powering our Defenses", description = "Ancient runestones once powered a protective barrier across the Eversong border.  Many were destroyed during Arthas' attack; others were stolen.\n\nOf the three that remain, only this one has retained its powers.  The runestone to the east might be salvageable, though.\n\nTake this crystal and instill its energy on the Eastern Runestone.  The process should take but a minute.  Beware though, nearby Scourge will be drawn to it and will seek to destroy it.  Do not let them!", sourceObjective = "Place the Infused Crystal at the Eastern Runestone and protect it from the Scourge for 1 minute. Return the Infused Crystal to Runewarden Deryan in Eversong Woods for a reward.", progress = "Have you succeeded in powering the runestone yet, {name}?", completion = "Excellent.  The defenses should hold off the Scourge a bit longer.  Thank you for lending us a hand, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8491] = { id = 8491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pelt Collection", description = "The springpaw that inhabit this region are known for their high quality pelts.  We've even seen night elf scum travel to these lands just to poach them.\n\nOur skirmishes with the Amani have put a bit of a strain on our supply of gear and our rangers don't have much time to hunt for pelts anymore.  If you'd be willing to lend a hand by collecting springpaw pelts, I'd be happy to reward you with a hand-crafted piece of armor.  You'll find springpaw stalkers all around the woods north of here.", sourceObjective = "Velan Brightoak at Fairbreeze Village in Eversong Woods wants you to bring him 6 Springpaw Pelts.", progress = "You're back.  Did you bring the pelts?", completion = "These will do perfectly, {name}.  Take this piece of armor as a reward.  I'll be able to make more with the pelts you brought me.", sourceObjectiveStatus = "unverified-source-field" }
quests[8492] = { id = 8492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Copper Bars!", description = "Hey there, {class}, you look fit enough to contribute to the war effort! We need all of the help that we can get here to put together the materiel needed for the Ahn'Qiraj War and it's your lucky day.\n\nI'm collecting copper bars in stacks of twenty. It's for a worthy cause, what do you say? Do you think you could help out the Alliance?", sourceObjective = "Bring 20 Copper Bars to Sergeant Stonebrow at the Military Ward in Ironforge.", progress = "Have you collected those twenty bars of copper yet, trooper?", completion = "You did it, lad! We'll get those copper bars onto the pile and put them to good use making the war materiel right away. It's the efforts of people like you that make me proud to serve the Alliance. Good work, soldier!\n\nAnd if you should happen to come across more copper bars, make sure that they find their way to me.", sourceObjectiveStatus = "unverified-source-field" }
quests[8493] = { id = 8493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs More Copper Bars!", description = "Back again {class}? Outstanding! We still need more stacks of copper bars if you can procure them for the Ahn'Qiraj war effort.  Will you help us out?", sourceObjective = "Bring 20 copper bars to Sergeant Stonebrow at the airfield in Dun Morogh.", progress = "Back again, {class}? Outstanding! The bars you've provided thus far are really going to help out in making all sorts of things for the war. I know, for example, that the copper is going to be used for parts of the steam tanks that are being built, as well as in a small fleet of gyrocopters that we're planning to deploy if time allows.\n\nDon't let the stacks here fool you though, we still need more copper bars if you can procure them for the Ahn'Qiraj war effort.  Will you help us out?", completion = "Excellent work! Digging around for that copper and smelting it must have been quite an adventure. Unless you bought them at the auction house. Either way, it works for me. You are to be commended for your contribution to the war effort, {class}. And please don't hesitate to bring me more copper bars if you have them.", sourceObjectiveStatus = "unverified-source-field" }
quests[8494] = { id = 8494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Iron Bars!", description = "Well hello there, <Mr./Ms.> Fancypants, aren't you a sight for sore eyes. In case you hadn't heard while you were out there \"adventuring\", the Alliance has been gearing up for a war in Ahn'Qiraj and is in need of iron bars... a whole mess of 'em. Bring them to me in stacks of twenty. We can count on you, right, {class}?", sourceObjective = "Bring 20 Iron Bars to Corporal Carnes at the Military Ward in Ironforge.", progress = "If you have those twenty bars of iron, I don't want to know where you have them hidden!", completion = "Well, well, if it isn't {name}. And you pulled through. I guess now I'll have to keep my eye on you. It hurts me to say this, but thanks for your efforts. The Alliance won't forget, and neither will I. Now get out there and bust your hump on whatever else needs collecting.", sourceObjectiveStatus = "unverified-source-field" }
quests[8495] = { id = 8495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs More Iron Bars!", description = "Back so soon? Stop making me re-evaluate my low opinion of you {class}, you're making me feel all gooey inside. So, as you can tell we still don't have enough iron bars for all of the weapons, armor, steam tanks and whatnot that need building for the bug hunt. Think you have it in you to bring back another stack of twenty iron bars in between all of those trips to Zul'Gurub, or wherever it is that you kids hang out these days?", sourceObjective = "Bring 20 iron bars to Corporal Carnes at the airfield in Dun Morogh.", progress = "Back so soon? Stop making me re-evaluate my low opinion of you, {class}, you're making me feel all gooey inside. So, as you can tell we still don't have enough iron bars for all of the weapons, armor, steam tanks and whatnot that need building for the bug hunt. Think you have it in you to bring back another stack of twenty iron bars in between all of those trips to Zul'Gurub, or wherever it is that you kids hang out these days?", completion = "Must be a cold day in the Burning Steppes. Look here, it's {name}, and he's brought me a gift. Twenty iron bars! Just what I always wanted.\n\nIn all seriousness though, thank you, {name}. You're a credit to yourself and the Alliance. Now get back out there and bring in more stuff for the war effort!", sourceObjectiveStatus = "unverified-source-field" }
quests[8496] = { id = 8496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bandages for the Field", description = "Our supply of bandages in the battlefield is running dangerously low after the recent casualties we have incurred.  Obtain a batch of first-aid supplies and deliver them to Windcaller Proudhorn in Cenarion Hold.", sourceObjective = "Bring 30 Heavy Runecloth Bandages, 30 Heavy Silk Bandages and 30 Heavy Mageweave Bandages to Windcaller Proudhorn at Cenarion Hold in Silithus. You must also bring Logistics Task Briefing X in order to complete this quest.", progress = "You have something for me, {name}?", completion = "Just in time.  These supplies will save lives, {name}.  Your work is appreciated.  Here's your next assignment.", sourceObjectiveStatus = "unverified-source-field" }
quests[8497] = { id = 8497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desert Survival Kits", description = "With the arrival of fresh recruits to Cenarion Hold comes the problem of keeping them alive in the desert.  Dehydration as well as numerous poisonous creatures present a serious threat to inexperienced volunteers.  Gather the supplies necessary for a desert survival kit and bring them to Calandrath in Cenarion Hold.", sourceObjective = "Bring 4 Globes of Water, 4 Powerful Anti-Venom and 4 Smoked Desert Dumplings to Calandrath at the inn in Cenarion Hold in Silithus. You must also bring Logistics Task Briefing I in order to complete this quest.", progress = "You have something for me?", completion = "Excellent!  We were in need of these, {name}.  Thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[8498] = { id = 8498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Battle Orders", description = "Our scouts have reported new battle orders being issued by the Twilight's Hammer leaders.  The orders are being distributed by Twilight Prophets under heavy escort.  Intercept the orders and bring them to Commander Mar'alith.", sourceObjective = "Obtain the Twilight Battle Orders and bring them Commander Mar'alith at Cenarion Hold in Silithus. You must also bring Tactical Task Briefing X in order to complete this quest.", progress = "You've brought something for me?", completion = "Excellent.  It's important to stay ahead of the enemy's next move.  This information will allow us to anticipate the Twilight's Hammer's attacks.", sourceObjectiveStatus = "unverified-source-field" }
quests[8499] = { id = 8499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Thorium Bars!", description = "It is very kind of you to inquire about the needs that the Alliance has. In addition to all of the other collection efforts underway, we are in need of a great quantity of thorium bars, which is the task that I am in charge of. The thorium will be used in the creation of many different things for the war, foremost of which is the construction of a battalion of steam tanks to be airlifted into Silithus as soon as they are completed. Can you aid us in this endeavor, {class}?", sourceObjective = "Bring 20 Thorium Bars to Dame Twinbraid at the Military Ward in Ironforge.", progress = "I do so hope that you have been successful in gathering the thorium bars that we spoke of earlier.", completion = "Oh thank you, {class}! Thank you! That's twenty down and an incalculable amount to go. You have the gratitude of the Alliance, and your efforts shall not go unrewarded. Speak to me again should you come across more thorium bars.", sourceObjectiveStatus = "unverified-source-field" }
quests[8500] = { id = 8500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs More Thorium Bars!", description = "It is so good to see you again {name}. I hope that you've been doing well. It's true that we are still in need of thorium bars. If you have them to spare I am collecting them for the Ahn'Qiraj war effort.", sourceObjective = "Bring 20 thorium bars to Dame Twinbraid at the airfield in Dun Morogh.", progress = "It is so good to see you again, {name}. I hope that you've been doing well. It's true that we are still in need of thorium bars. If you have them to spare I am collecting them for the Ahn'Qiraj war effort.", completion = "Excellent, {class}! A job well done. I'll see to it that those bars get onto the pallet and into the hands of the blacksmiths and engineers that are hard at work building up the supplies for our army. Thank you again, and if you come across more thorium bars be sure to drop by.", sourceObjectiveStatus = "unverified-source-field" }
quests[8501] = { id = 8501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Target: Hive'Ashi Stingers", description = "As the war effort mounts, the silithid presence in the area presents an ever increasing threat to our operations.  You've been selected to partake on an assault on Hive'Ashi where your primary target will consist of the airborne Hive'Ashi stingers.\n\nReport back to Commander Mar'alith after your task is completed.", sourceObjective = "Kill 30 Hive'Ashi Stingers and report back to Commander Mar'alith at Cenarion Hold in Silithus. You must also bring Combat Task Briefing XII in order to complete this quest.", progress = "You wish to tell me something, {name}?", completion = "Excellent work, {name}.  Your part in the attack on Hive'Ashi has been noted.", sourceObjectiveStatus = "unverified-source-field" }
quests[8502] = { id = 8502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Target: Hive'Ashi Workers", description = "As the war effort mounts, the silithid presence in the area presents an ever increasing threat to our operations.  You've been selected to partake on an assault on Hive'Ashi where your primary target will consist of Hive'Ashi workers.\n\nReport back to Commander Mar'alith after your task is completed.", sourceObjective = "Slay 30 Hive'Ashi Workers and report back to Commander Mar'alith at Cenarion Hold in Silithus. You must also bring Combat Task Briefing III in order to complete this quest.", progress = "You have something to tell me, {class}?", completion = "Excellent work, {name}.  Without their workers, the silithid will have a hard time repairing any damage inflicted to their hive's structure.", sourceObjectiveStatus = "unverified-source-field" }
quests[8503] = { id = 8503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Stranglekelp!", description = "So, {class}, did I already tell you about all of the fabulous uses stranglekelp has? I did? Oh well... in any case we need a lot of it, and when I say a lot, I mean A LOT! Do you think that you could help us out? I know that it means going without all of those wonderful things that you can make with it, but it's for a good cause!", sourceObjective = "Bring 20 Stranglekelp to Private Draxlegauge at the Military Ward in Ironforge.", progress = "It's not true! I'd never skim any stranglekelp off the top of the stacks here. One might be tempted to though considering that it's practically a panacea of utilitarian usefulness. *cough* You don't happen to have that stranglekelp we discussed earlier?", completion = "Hooray! That's another twenty down. You're the best. I suppose that I should get these all packed away before they wither. So much stranglekelp, so little time!\n\nThanks again, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[8504] = { id = 8504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs More Stranglekelp!", description = "Well hello again there... what was it? Ah yes, {name}! Come to see if I still need more stranglekelp have you? Well, it's your lucky day, because the answer to that very important question is a very affirmative YES! Think you could gather up twenty more?", sourceObjective = "Bring 20 stranglekelp to Private Draxlegauge at the airfield in Dun Morogh.", progress = "Well hello again there... what was it? Ah yes, {name}! Come to see if I still need more stranglekelp have you? Well, it's your lucky day, because the answer to that very important question is a very affirmative YES! Think you could gather up twenty more?", completion = "Oh goodness that's a quite a load of stranglekelp you have there. Quick, let's get that into a box to keep it fresh. You've done me... us, the Alliance a great favor by bringing that batch in. I'll make sure that everyone knows that it was you, the great {name}, that helped to tip the scales in the Ahn'Qiraj war effort with your contribution of stranglekelp!", sourceObjectiveStatus = "unverified-source-field" }
quests[8505] = { id = 8505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Purple Lotus!", description = "{class}, the purple lotus is a flower with a plentitude of uses. I am here at the request of the Alliance as an authority on those applications, to preserve the herbs collected and to ensure that their war effort acquires enough purple lotus to sustain whatever function they plan for it.\n\nI would like for you to travel out into the world and return to me with some of these flowers. Is that something that you can do?", sourceObjective = "Bring 20 Purple Lotus to Master Nightsong at the Military Ward in Ironforge.", progress = "Do you have the purple lotus herbs that I requested?", completion = "Your contribution is greatly appreciated, {class}. It is only through the combined efforts of all that we shall be able to repel the ruthless advance of the silithid and whatever force is driving them forth. Even the Horde is amassing their own collection of purple lotus. Should you come across more, please return to me here.", sourceObjectiveStatus = "unverified-source-field" }
quests[8506] = { id = 8506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs More Purple Lotus!", description = "Welcome back {class}. Our collection grows, but even now we have a need for additional purple lotus. If it is still within your power to gather more of the herb, I entreat you to do so and return them to me here.", sourceObjective = "Bring 20 purple lotus to Master Nightsong at the airfield in Dun Morogh.", progress = "Welcome back, {class}. Our collection grows, but even now we have a need for additional purple lotus. If it is still within your power to gather more of the herb, I entreat you to do so and return them to me here.", completion = "I gladly accept your contribution on behalf of the Alliance, {name}. Your efforts will directly lead to the creation of several potions and oils in support of our men and women in the field. Thank you, and should come across more, please consider returning to me.", sourceObjectiveStatus = "unverified-source-field" }
quests[8507] = { id = 8507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Duty", description = "Greetings, {name}.  Before I assign you to more involved tasks in the war, you'll need to do your share of field duty.  \n\nYou will find Captain Blackanvil's Ironforge Brigade outside Hive'Zora.\n\nReport to him or his lieutenant, Janela Stouthammer and come back to me.  I shall have a more advanced assignment for you ready.\n\nOh and please do us a favor and stay away from the Orgrimmar Legion.  We've been forced to keep the two forces well apart from one another due to mutual animosity.", sourceObjective = "Report for duty at the Ironforge Brigade post near Hive'Zora. Prepare your Unsigned Field Duty Papers and obtain Signed Field Duty Papers from Captain Blackanvil and return to Windcaller Kaldon at Cenarion Hold in Silithus.\n\nNote: Healing or casting beneficial spells on a member of the Ironforge Brigade will flag you for PvP.", progress = "You'll find Captain Blackanvil's force stationed outside Hive'Zora.  Talk to his lieutenant, Janela Stouthammer, if you can't find him.", completion = "Very well, {name}.  I've prepared a set of tasks that should make optimal use of your skills.\n\nWith the continued efforts of you and people like you, our enemy will soon be vanquished once and for all!\n\nShould you require a new mission briefing, return to Captain Blackanvil.", sourceObjectiveStatus = "unverified-source-field" }
quests[8508] = { id = 8508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Duty Papers", progress = "I take it you want those papers signed, lad?", completion = "Aye, I suppose that little skirmish will pass as field duty nowadays.  Take these back to Cenarion Hold, I'm sure they'll have a cushy job ready for you.\n\nOff you go!" }
quests[8509] = { id = 8509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Arthas' Tears!", description = "I'll keep it simple and to the point, {class}. The Alliance needs to collect a large quantity of Arthas' Tears for the Ahn'Qiraj war effort. Don't ask me what for; I'm just following orders. But I'd like you to gather up as many of the herbs as you can and bring them back to me here. Are you willing to do that?", sourceObjective = "Bring 20 Arthas' Tears to Sergeant Major Germaine at the Military Ward in Ironforge.", progress = "What's that? Speak up, {class}! Have you got that shipment of Arthas' Tears I asked for?", completion = "Good work, {class}. I must say that I'm pleasantly surprised. You would not believe the number of people that have come by, offering to help, but never returning. Let me just get those into a crate and tallied with your name on it, and then we can talk again about whether I need anymore of those plants.", sourceObjectiveStatus = "unverified-source-field" }
quests[8510] = { id = 8510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs More Arthas' Tears!", description = "Ok, so it looks like I still need more Arthas' Tears. I would imagine that you will be able to find them in the general location that you gathered them up for me last time. The quicker we get these, the faster we can start up the offensive against the forces at Ahn'Qiraj.\n\nYou gonna help us out again {class}?", sourceObjective = "Bring 20 arthas' tears to Sergeant Major Germaine at the airfield in Dun Morogh.", progress = "Ok, so it looks like I still need more Arthas' Tears, {class}. I would imagine that you will be able to find them in the general location that you gathered them up last time. The war effort is coming along nicely, but the quicker we get these, the faster we can start up the offensive against the forces at Ahn'Qiraj.\n\nYou gonna help us out again, {name}?", completion = "Simply outstanding, {name}! You're a real credit to the Alliance. I'll make sure to get these herbs packed away until someone comes to make them into something useful for the war. Feel free to come back around anytime, especially if you have more Arthas' Tears for me.", sourceObjectiveStatus = "unverified-source-field" }
quests[8511] = { id = 8511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Light Leather!", description = "We Stoneflayers have a long history of being skinners, {class}. That's why the Alliance has asked my family to help out with the collection of light leather for the Ahn'Qiraj war effort. I'm here to see to it that the leather is tanned correctly for whatever they want to put it to use for. But we need your help.\n\nSince I have to be here doing that, I need you to go out and collect the skins, returning them to me here. What do you say, <lad/lass>, will you give it a go?", sourceObjective = "Bring 10 Light Leather to Bonnie Stoneflayer at the Military Ward in Ironforge.", progress = "{class}, I do so hope that's the light leather you promised.", completion = "I dare say the Alliance is going to be very happy with your skins here, {class}. I'll make sure that not a one goes to waste. Thank you, and make sure that you check back in with me once I've counted them up to see if we need more.", sourceObjectiveStatus = "unverified-source-field" }
quests[8512] = { id = 8512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs More Light Leather!", description = "Good to see you again {name}. It does appear that we need more light leather for the creation of the various war materiel. If you could bring me a stack of ten that would be just perfect.", sourceObjective = "Bring 10 light leather to Bonnie Stoneflayer at the airfield in Dun Morogh.", progress = "Good to see you again, {name}. It does appear that we need more light leather for the creation of the various war materiels. If you would bring me a stack of ten, that would be just perfect.", completion = "Thank you for your generous donation, {name}. I'm going to get those onto the pile right now, and in no time I'm sure that they'll get changed into a nice set of armor, some leather patches, or used for something else in our preparations. Seems like we're always in need of more light leather. Come back and visit me soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[8513] = { id = 8513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Medium Leather!", description = "Yes <sir/ma'am>, I have been charged with collecting and tracking all of the medium leather gathered for the war effort. If you have the wherewithal to gather medium leather, from whatever source, then please bring them to me here. I sure would appreciate a hand with this if you can spare the time.", sourceObjective = "Bring 10 Medium Leather to Private Porter at the Military Ward in Ironforge.", progress = "Yes sir, I remember you. Is that the medium leather you have with you there?", completion = "Wow! Seems like you were just here volunteering to help. Thank you very much for the donation. I'll just get those all packed up and counted. You sure do know how to brighten a fella's day.", sourceObjectiveStatus = "unverified-source-field" }
quests[8514] = { id = 8514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs More Medium Leather!", sourceObjective = "Bring 10 medium leather to Private Porter at the airfield in Dun Morogh.", progress = "Yes sir, looks like we've collected many pieces of medium leather, but we need more. I can assure you that it will all be put to good use; not one piece will get wasted. I know it's a lot to ask, but if you're still willing, I could use your help in attempting to put a dent in the rest of my quota.", completion = "Golly, that sure is a lot of medium leather that you've brought round, sir! I'm gonna make sure that all of that gets put to proper use, yes indeed. With your help we'll have filled our estimation for medium leather in no time!\n\nThanks, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[8515] = { id = 8515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Thick Leather!", description = "Oh boy, this is going to be great! {class}, the Ahn'Qiraj war effort is in full swing, and I've been put in charge of keeping track of all of the thick leather that comes in. We'll make tons of things with it, but first we need to get a ton of it. And I mean that literally! That's where you come in.\n\nSo, do you think you can go out there and bring me back a nice, fat stack of thick leather? Do yah, do yah?!", sourceObjective = "Bring 10 Thick Leather to Marta Finespindle at the Military Ward in Ironforge.", progress = "Is that the thick leather you have there in your pack, {class}? Is it? I can't wait for you to hand it over! Everyone is going to be so pleased with us don't you think?", completion = "Oh, I knew you could do it, {class}, I just knew it! I'll get these into the right hands as soon as I can. Now, let's see here. Hmm, looks like our tally is coming along rather nicely. You should check back with me in just a moment once I'm done counting to see if we need more.  Cuz if we do, you're the one I want out there gathering it up for me!", sourceObjectiveStatus = "unverified-source-field" }
quests[8516] = { id = 8516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs More Thick Leather!", sourceObjective = "Bring 10 thick leather to Marta Finespindle at the airfield in Dun Morogh.", progress = "Yep, the stack's still not high enough. {name}, we still haven't reached our thick leather goal. Just think of all the things that we can make with all of that leather! All kinds of armor and weapons. Stuff for inside the steam tanks and rifle scopes! And engineering goggles, those are always fun!\n\nYou gonna bring me back some more thick leather?", completion = "You did it again! That is simply amazing how you go out there, collect all of this stuff, and then bring it back here and hand it over. I tell ya, when they find out how much you've been helping out around here you're not going to be able to walk down the street without people asking you for your autograph!\n\nThanks again for your very generous donation of thick leather, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8517] = { id = 8517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Linen Bandages!", description = "The war at Ahn'Qiraj is going to be long and bloody. It is a very wise thing that the Alliance is doing by enlisting the aid of you, and those like you, to build up the materiel necessary before plunging headlong into conflict.\n\nI have been asked to head up the collection of linen bandages for the war, and I am hoping that you are going to assist me in amassing as many as we need. It is no light matter, but at least the linen bandages are the least difficult to create. Are you with us, {class}?", sourceObjective = "Bring 20 Linen Bandages to Sentinel Silversky at the Military Ward in Ironforge.", progress = "Do you have the twenty linen bandages that I require, {class}?", completion = "Many are the soldiers that will benefit from your contribution here today, {class}. I shall see to it personally that the Alliance is made aware of your efforts. Allow me a moment to store these bandages properly and update my count, and then you should check back with me to see if I am in need of more.\n\nMay the Light of Elune shine upon you, {race}!", sourceObjectiveStatus = "unverified-source-field" }
quests[8518] = { id = 8518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs More Linen Bandages!", description = "Ever am I amazed by the selflessness exhibited when so many would instead turn to selfishness instead. {class}, I am still in need of a number of linen bandages before my assignment here is fulfilled. Will you aid me once more in the collection of those bandages?", sourceObjective = "Bring 20 linen bandages to Sentinel Silversky at the airfield in Dun Morogh.", progress = "Ever am I amazed by the selflessness exhibited when so many would instead turn to selfishness instead. {class}, I am still in need of a number of linen bandages before my assignment here is fulfilled. Will you aid me once more in the collection of those bandages?", completion = "You are to be commended, {name}. While there are those that would take advantage of the economics of our war footing to line their pockets in a fervor of greed, you have proven time and again that your devotion to the Alliance, and indeed to all of Azeroth, comes first.\n\nBlessings of Elune be with you always!", sourceObjectiveStatus = "unverified-source-field" }
quests[8519] = { id = 8519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Pawn on the Eternal Board", description = "As you regain your composure and focus your gaze, you notice that something stirs within the crystal. Upon closer inspection, you realize that you are looking into the past... a memory... long forgotten.", sourceObjective = "Learn all that you can of the past, then speak with Anachronos at the Caverns of Time in Tanaris.", completion = "After Staghelm's betrayal, I gathered the shattered pieces of the Scepter of the Shifting Sands and returned here. I had every intention of protecting the scepter from those that would seek to use it to cause harm to our world - thus was born the charge of the Dragonflights.\n\nA scepter divided amongst the four mighty Aspects would prove to be nearly impossible to restore for those willfully seeking chaos... or so I thought. What a fool I was. Even now I am hunted by that cursed flight.", sourceObjectiveStatus = "unverified-source-field" }
quests[8520] = { id = 8520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Silk Bandages!", description = "With the Ahn'Qiraj War looming we need to do everything that we can to see to it that our soldiers have everything that they need. We're doing just that right here. For my part I've been placed in charge of seeing to it that we collect enough silk bandages.\n\nDo you think you can help me out, {class}?", sourceObjective = "Bring 20 Silk Bandages to Nurse Stonefield at the Military Ward in Ironforge.", progress = "Hello, {class}, have you been able to get those twenty silk bandages yet?", completion = "{class}, you did it! Thanks to you we are another step closer to achieving our goal with silk bandages. I'll get them stored away, and then we can talk more if you like.", sourceObjectiveStatus = "unverified-source-field" }
quests[8521] = { id = 8521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs More Silk Bandages!", sourceObjective = "Bring 20 silk bandages to Nurse Stonefield at the airfield in Dun Morogh.", progress = "It is very kind of you to offer to help me again, {class}. It looks like we've collected a goodly number of the silk bandages we've been tasked with, but we still need more. {name}, is there any way that you could see fit to put together another bundle and return them to me here? The Alliance and I will be most grateful.", completion = "You are such a selfless person. Thank you very much for your contribution to the war effort. It's people like you that are going to make the difference between success and failure at Ahn'Qiraj. I just hope that all of this will be enough.\n\nThanks again, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8522] = { id = 8522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Runecloth Bandages!", description = "Argue the merits of the war if you will, {class}, but it has already been set in motion. Look around you at your family and friends, and then ask yourself what it is that you can do to see to it that if they are involved, they will have every advantage to survive the conflagration.\n\nTo that end, I am collecting runecloth bandages here from whatever source. Would you like to make a donation?", sourceObjective = "Bring 20 Runecloth Bandages to Keeper Moonshade at the Military Ward in Ironforge.", progress = "The days pass one after the other, and still we go on. {class}, have you those runecloth bandages?", completion = "You are to be commended, {class}, for your perseverance in this task. I shall put these bandages away, and then I should like to talk to you again about the possibility of your collecting even more runecloth bandages.", sourceObjectiveStatus = "unverified-source-field" }
quests[8523] = { id = 8523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs More Runecloth Bandages!", description = "So it is that we come to discuss pressing matters yet again {class}. Once more I thank you for your previous efforts; it is not everyone who would give so selflessly. But there is still more work to do.\n\n{name}, will you once more collect runecloth bandages and return them to me here?", sourceObjective = "Bring 20 runecloth bandages to Keeper Moonshade at the airfield in Dun Morogh.", progress = "So it is that we come to discuss pressing matters yet again, {class}. Once more I thank you for your previous efforts; it is not everyone who would give so selflessly. But there is still more work to do.\n\n{name}, will you once more collect runecloth bandages and return them to me here?", completion = "This is a fine road we are traveling together, {name}. You make an excellent working companion. Once more do I give thanks to you for your efforts on behalf of the entire Alliance. Come and talk again with me soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[8524] = { id = 8524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Rainbow Fin Albacore!", description = "Hey there, friend! If I were to say to you, 'Don't you think that soldiers should have food to eat like anyone else?', you would of course reply, 'yes'. I agree with you 110%! I'm glad we're in accord. All I need for you to do is to head out there, fish up a whole bunch of raw rainbow fin albacore, and then cook it all up and bring it back to me right here. Mmm, mmm, I can taste it already.", sourceObjective = "Bring 20 Rainbow Fin Albacore to Slicky Gastronome at the Military Ward in Ironforge.", progress = "I'm willing to lay odds that you've returned with all of that rainbow fin albacore we were talking about before, right, {class}?", completion = "Two for the Alliance, one for me, two for the Alliance, one for me. Hey there, fishmonger, excellent work. I can see that you're going to be a real credit to the club. Looks to me like we probably need more of that albacore though. Why don't you head on out and rustle up a mite more. I can hear my stomach rumbling already.", sourceObjectiveStatus = "unverified-source-field" }
quests[8525] = { id = 8525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs More Rainbow Fin Albacore!", description = "What! You again? Well I'll be a monkey's uncle... except that I'm a gnome. Slicky Gastronome to be precise! So you're back to help out again eh? Well, I can't say as I blame you. Don't you just love the smell of all of that food? <drool>\n\nEnough loitering! Get out there and bring me back more rainbow fin albacore!", sourceObjective = "Bring 20 rainbow fin albacore to Slicky Gastronome at the airfield in Dun Morogh.", progress = "What! You again? Well I'll be a monkey's uncle... except that I'm a gnome. Slicky Gastronome to be precise! So you're back to help out again, eh? Well, I can't say as I blame you. Don't you just love the smell of all of that food? <drool>\n\nEnough loitering! Get out there and bring me back more rainbow fin albacore!", completion = "I knew that you had it in you, kid. You've got the look of someone who knows what he likes. Specifically that you like pleasing me and the powers that be. And that you have, I guarantee.\n\nHaha, ok, I'll just get these fish properly stashed away, and then you and I can have a little talk concerning you collecting another twenty albacore.", sourceObjectiveStatus = "unverified-source-field" }
quests[8526] = { id = 8526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Roast Raptor!", description = "Oh, how's it going, {class}? I see that you're interested in maybe gathering up food for the coming war at Ahn'Qiraj? Somehow my dad thought that it would be a good learning experience for me if I were to volunteer to help out here. Big mistake. I don't even like to eat meat.\n\nAnyway, if you feel like it, you could bring me back a lot of roast raptor. Apparently that's what all of the soldiers are going to want.", sourceObjective = "Bring 20 Roast Raptor to Sarah Sadwhistle at the Military Ward in Ironforge.", progress = "So do you have all of that roast raptor yet?", completion = "Gee, that's swell. Thanks for bringing me all of this burnt animal flesh, {class}. I'll just put it onto the pile over there. I'm sure that someone will take care of it. I suppose if you have some time on your hands that you might want to bring me more?", sourceObjectiveStatus = "unverified-source-field" }
quests[8527] = { id = 8527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs More Roast Raptor!", description = "Hi again {class}. I can tell you're very excited about all of this. So I suppose you want to bring me another twenty roast raptor. Great. Well you do that. I guess I'll see you when you get back.", sourceObjective = "Bring 20 roast raptor to Sarah Sadwhistle at the airfield in Dun Morogh.", progress = "Hi again, {class}. I can tell you're very excited about all of this. So I suppose you want to bring me another twenty roast raptor? Great. Well you do that. I guess I'll see you when you get back.", completion = "Wow, you're a real go-getter. You make me tired just looking at you. Anyway, thanks from the Alliance and all that. I'll make sure that all of that dead meat gets packed away. I guess you could check back with me later to see if we still need more of it, though it's starting to stink up the place if you ask me.", sourceObjectiveStatus = "unverified-source-field" }
quests[8528] = { id = 8528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Spotted Yellowtail!", description = "It may not seem heroic to gather up cooked fish, but do not underestimate the value of preparation, young {class}. Soldiers need to eat like anyone else, and we're here to do our part to make sure they have what they need once the war in Ahn'Qiraj commences.\n\nAccordingly, I am stockpiling spotted yellowtail, a versatile source of sustenance that stores well and can be used in many different dishes. It also doesn't have the odor of some other saltwater fish. Are you willing to aid me in this endeavor?", sourceObjective = "Bring 20 Spotted Yellowtail to Huntress Swiftriver at the Military Ward in Ironforge.", progress = "I am confident that you are returning so soon with the spotted yellowtail we discussed.", completion = "Thank you for this gift, {class}, and in such a timely manner as well. Our soldiers will surely not lack for something to eat. Just let me get these fish stored away properly and then you and I can discuss a second haul if you're willing.", sourceObjectiveStatus = "unverified-source-field" }
quests[8529] = { id = 8529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs More Spotted Yellowtail!", description = "If you're still willing I'd like to send you back out to bring in another haul of spotted yellowtail, {name}. I'd imagine with the expertise you gained the first time out that this catch should be much faster and easier. Are you game?", sourceObjective = "Bring 20 spotted yellowtail to Huntress Swiftriver at the airfield in Dun Morogh.", progress = "If you're still willing I'd like to send you back out to bring in another haul of spotted yellowtail, {name}. I'd imagine with the expertise you gained the first time out that this catch should be much faster and easier. Are you game?", completion = "You are a true member of the Alliance, {name}. Your efforts shall not go unnoticed, or unappreciated. And thank you for cooking up the fish as well. I will see to it that they are stored away properly, and then I'll need to update my count. Every one brings us that much closer to catching our goal.", sourceObjectiveStatus = "unverified-source-field" }
quests[8530] = { id = 8530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Singed Corestones!", description = "{class}, I need your help. In the Molten Core there are these stones, singed Corestones to be precise, that we need to harvest for the Ahn'Qiraj war effort. I'm told that our blacksmiths and engineers can put them to good use, so that's where you come in. I need you to go into the Molten Core and gather up as many of these corestones as you can. Of course, you'll want to talk thirty-nine of your closest friends along with you.", sourceObjective = "Bring 50 singed corestones to Commander Stronghammer at the airfield in Dun Morogh.", sourceObjectiveStatus = "unverified-source-field" }
quests[8532] = { id = 8532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs Copper Bars!", description = "So glad that you've decided to help out here. Not everyone would, so I need to make sure you understand what it is that I need. Copper bars, not copper ore. We don't have the time or people to do all of the smelting ourselves, so if you would be so kind as to take care of that, your efforts will be duly noted. Is that something that you can handle, {class}?", sourceObjective = "Bring 20 Copper Bars to Miner Cromwell at the Valley of Spirits in Orgrimmar.", progress = "I hope that's the twenty copper bars you have there with you, {class}.", completion = "These bars will do, and thanks for not shining them. No sense in making them pretty when they're going to be mangled for whatever materiel needs to be built for the war. I'll take care of putting them on the stacks, and I'll make sure that they are put to proper use. Speak to me again if you're interested in bringing in another twenty.", sourceObjectiveStatus = "unverified-source-field" }
quests[8533] = { id = 8533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs More Copper Bars!", description = "Back so soon? You'll be a real miner in no time {class}. So, you already know the drill; I need you to go out, mine up a mess of copper ore, smelt it into bars and bring it back to me here. I know that's something you're capable of, the question is, are you willing?", sourceObjective = "Bring 20 copper bars to Miner Cromwell in Durotar.", progress = "Back so soon? You'll be a real miner in no time, {class}. So, you already know the drill; I need you to go out, mine up a mess of copper ore, smelt it into bars and bring it back to me here. I know that's something you're capable of, the question is, are you willing?", completion = "You've proven yourself to me yet again, {class}. I will see to it that this copper is used in due time. For now though, I need to get these copper bars onto the pallet and tallied. If you still feel inclined, I could probably use your help in gathering even more copper bars.", sourceObjectiveStatus = "unverified-source-field" }
quests[8534] = { id = 8534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hive'Zora Scout Report", description = "We've sent our best scouts deep into the silithid hives to gather intelligence.  Scout Azenel has been watching the silithid movements at Hive'Zora for several days now.  Find her and obtain a written report.  We need to be able to act on that information as soon as possible, {name}.", sourceObjective = "Contact Cenarion Scout Azenel inside Hive'Zora and return the Hive'Zora Scout Report to Windcaller Proudhorn at Cenarion Hold. You must also bring Tactical Task Briefing VI in order to complete this quest.", progress = "You'll find Scout Azenel inside Hive'Zora.  Hurry, {name}!  Time is of the essence.", completion = "Your efforts are greatly appreciated, {name}.  I'll read these scouting reports right away, feel free to go over your next assignment.", sourceObjectiveStatus = "unverified-source-field" }
quests[8535] = { id = 8535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoary Templar", description = "The Twilight's Hammer and the elemental nobles they worship present a formidable threat to our operations in Silithus.  With the new enemies we're facing inside Ahn'Qiraj, we cannot afford to lower our guard to our enemies outside.\n\nFind a way to summon and destroy a Hoary Templar and report to Bor Wildmane.", sourceObjective = "Summon and slay a Hoary Templar and report back to Bor Wildmane in Cenarion Hold. You must also bring Tactical Task Briefing IV in order to complete this quest.", progress = "Is your task done yet, {name}?", completion = "Good job, {name}.  Here's your next assignment.", sourceObjectiveStatus = "unverified-source-field" }
quests[8536] = { id = 8536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Earthen Templar", description = "The Twilight's Hammer and the elemental nobles they worship present a formidable threat to our operations in Silithus.  With the new enemies we're facing inside Ahn'Qiraj, we cannot afford to lower our guard to our enemies outside.\n\nFind a way to summon and destroy an Earthen Templar and report to Bor Wildmane.", sourceObjective = "Summon and slay an Earthen Templar and report back to Bor Wildmane in Cenarion Hold. You must also bring Tactical Task Briefing III in order to complete this quest.", progress = "Is your task done yet, {name}?", completion = "Good job, {name}.  Here's your next assignment.", sourceObjectiveStatus = "unverified-source-field" }
quests[8537] = { id = 8537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crimson Templar", description = "The Twilight's Hammer and the elemental nobles they worship present a formidable threat to our operations in Silithus.  With the new enemies we're facing inside Ahn'Qiraj, we cannot afford to lower our guard to our enemies outside.\n\nFind a way to summon and destroy a Crimson Templar and report to Bor Wildmane.", sourceObjective = "Summon and slay a Crimson Templar and report back to Bor Wildmane in Cenarion Hold. You must also bring Tactical Task Briefing II in order to complete this quest.", progress = "Is your task done yet, {name}?", completion = "Good job, {name}.  Here's your next assignment.", sourceObjectiveStatus = "unverified-source-field" }
quests[8538] = { id = 8538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Four Dukes", description = "The links between the Twilight's Hammer and the Abyssal Council are proving to be more important than we had expected.\n\nWe believe the elemental nobles known as the Abyssal Dukes are one of the primary force organizing the Twilight's Hammer cultists.  Find a way to lure the four Abyssal Dukes into our plane of existence and destroy them!\n\nYour dedication and prowess in past assignments have led us to choose you for this particular assignment.  We are certain you will succeed in this endeavor.", sourceObjective = "Find a way to summon and slay the Duke of Cynders, the Duke of Fathoms, the Duke of Zephyrs and the Duke of Shards and report back to Commander Mar'alith in Cenarion Hold. You must also bring Tactical Task Briefing V in order to complete this quest.", progress = "Is your task done yet, {name}?", completion = "You have achieved a great accomplishment for our cause today, {name}.  You've vanquished some of our most powerful enemies.  For that I greatly commend you.", sourceObjectiveStatus = "unverified-source-field" }
quests[8539] = { id = 8539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Target: Hive'Zora Hive Sisters", description = "Reinforcements have been called on to join the assault on Hive'Zora.  You have been selected to target Hive'Zora hive sisters.  Report back to Commander Mar'alith after completing your task.", sourceObjective = "Slay 30 Hive'Zora Hive Sisters and report back to Commander Mar'alith at Cenarion Hold in Silithus. You must also bring Combat Task Briefing V in order to complete this quest.", progress = "You have something to tell me, {class}?", completion = "Excellent work, {name}.  You're a worthy ally.", sourceObjectiveStatus = "unverified-source-field" }
quests[8540] = { id = 8540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boots for the Guard", description = "The mounted division of the Cenarion Hold guard is in short supply of ornate mithril boots.  Procure a batch and deliver them immediately to Captain Vish Kozus in Cenarion Hold.", sourceObjective = "Bring 3 Ornate Mithril Boots to Vish Kozus, Captain of the Guard at Cenarion Hold in Silithus. You must also bring Logistics Task Briefing II in order to complete this quest.", progress = "You have something for me?", completion = "Excellent.  We were in need of these, {name}.  Good work.", sourceObjectiveStatus = "unverified-source-field" }
quests[8541] = { id = 8541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grinding Stones for the Guard", description = "The Cenarion Hold guard is in short supply of grinding stones.  Procure a batch and deliver them immediately to Captain Vish Kozus in Cenarion Hold.", sourceObjective = "Bring 10 Dense Grinding Stones, 10 Solid Grinding Stones and 10 Heavy Grinding Stones to Vish Kozus, Captain of the Guard at Cenarion Hold in Silithus. You must also bring Logistics Task Briefing III in order to complete this quest.", progress = "You have something for me?", completion = "Excellent.  We were in need of these, {name}.  Good work.", sourceObjectiveStatus = "unverified-source-field" }
quests[8542] = { id = 8542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs Tin Bars!", description = "Lok'tar, {race}, I'm sure you already know that we're going to war at Ahn'Qiraj with the insects. But first the Warchief has decided that we're going to do something called 'prepare'. Though I'd rather be sharpening weapons and hammering armor into shape, I'm proud to have been chosen to be in charge of tin bar collection here. But I cannot do that without your help.\n\nSo I need you to go out and make tin bars and bring them back to me here. I think I'm going to need more than I can count.", sourceObjective = "Bring 20 Tin Bars to Grunt Maug at the Valley of Spirits in Orgrimmar.", progress = "How many tin bars do you have there, {class}? After the war I think I'm going to need someone to teach me how to count.", completion = "Well, I guess that looks like the right number of tin bars. Don't try to fool me, {class}! Counting makes my skull hurt. Now I go and put these bars on the stack and you go out and bring me back more of the same.", sourceObjectiveStatus = "unverified-source-field" }
quests[8543] = { id = 8543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs More Tin Bars!", description = "Very good, I see that you are serious about the war. I'm a little edgy waiting for it to start though, which means I'm going to get angry if you don't start bringing in the goods faster. Maybe I can just practice on you instead.\n\nHar! Maybe not, 'cuz then who would bring me back the tin bars?", sourceObjective = "Bring 20 tin bars to Grunt Maug in Durotar.", progress = "Very good, I see that you are serious about the war. I'm a little edgy waiting for it to start though, as I'm sure you are as well, {class}. It will be glorious when it begins. The Horde running over the sands of the Silithus desert, weapons in hand, charging headlong into the insect masses. Great honor will be had that day by all!\n\nHar! But first we need more tin bars. Funny how such a small thing may make such a huge difference, don't you think?", completion = "Throm'ka, {name}. You honor me and the Horde with your tin bars. I will put them on the stack and then they will come and make things from them. And then when that is all done we will go to war and show the puny Alliance how to fight the bugs.\n\nNow bring me back more tin bars!", sourceObjectiveStatus = "unverified-source-field" }
quests[8544] = { id = 8544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conqueror's Spaulders", description = "It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon.\n\nBring me the bindings worn by the highest Qiraji leaders and I shall shape them into a set of pauldrons more dreadful than even the wings of Nefarian himself!", sourceObjective = "Bring the Qiraji Bindings of Command, 2 Idols of Night, 5 Stone Scarabs and 5 Clay Scarabs to Andorgos in Ahn'Qiraj. You must also attain Neutral reputation with the Brood of Nozdormu to complete this quest.", progress = "Have you collected the components I require?", completion = "From the materials you bring and from the scales of our fallen Qiraji foes I make you these pauldrons, mortal.  May they grant you the protection you need and may the sight of them strike fear into our enemies.", sourceObjectiveStatus = "unverified-source-field" }
quests[8545] = { id = 8545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs Mithril Bars!", description = "{class}, the war it is comin' and the only thing we can do is prepare for it. That be where you and I can help each other, mon. Ya see, they put me in charge of collectin' all the mithril bars we be needin' ta build for all the things we gonna need. An I still be needin' more!\n\nSo, I be hopin' that you can get out there an mine us up some mithril, then smelt it into bars. Sound like something you can do for us?", sourceObjective = "Bring 20 Mithril Bars to Senior Sergeant T'kelah at the Valley of Spirits in Orgrimmar.", progress = "It sure would be nice to be havin' all of the mithril bars that we be needin' for the Ahn'Qiraj war effort. Is that why you be back, mon? You got my bars?", completion = "This be a good start for you an me, {class}. That be another twenty mithril bars that I can be puttin' on the stacks an checkin' off of the list. It all gonna be put to good use makin' the war materiel.\n\nBe makin' sure that you check back in with me 'cuz you know it be lookin' like we gonna need even more of those mithril bars.", sourceObjectiveStatus = "unverified-source-field" }
quests[8546] = { id = 8546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs More Mithril Bars!", progress = "Yup, I be glad you're here, mon. You helped me before, and now I need your help again. We still lookin' ta bring in more mithril bars for the war effort; gonna build lots of armor and weapons and things to go squish them bugs at Ahn'Qiraj.\n\nSo if you be a true friend, you bring me back more stacks of mithril bars. I take all you got until we hit our quota. You have some for me now?", completion = "That be good work {name}! Another twenty bars get us that much closer to the goal, and get us more war materiel. I see to it they get put away. And if you get another stack of mithril bars mon, you make sure to be bringin' them here to me." }
quests[8547] = { id = 8547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Marsilla Dawnstar in Falconwing Square.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!", sourceObjective = "Bring the Falconwing Square Gift Voucher to Marsilla Dawnstar in Falconwing Square.", progress = "Greetings!  It is a pleasure to meet you!\n\nI see you have a special voucher.  Give it to me and I will offer you something in exchange.", completion = "You are indeed a special hero, {name}. We welcome you to the world of Azeroth, and offer you one of these unique gifts!", sourceObjectiveStatus = "unverified-source-field" }
quests[8548] = { id = 8548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Volunteer's Battlegear", description = "The badges you collect from performing combat, logistics and tactical assignments for Cenarion Hold are more than just for show, {name}.\n\nYou'd be wise to hold on to them.  As you prove your loyalty to our organization I can offer you some of the gear we reserve for our closest allies in exchange for those badges.", sourceObjective = "Bring 5 Cenarion Combat Badges, 3 Cenarion Logistics Badges and 7 Cenarion Tactical Badges to Vargus at Cenarion Hold in Silithus. You must also attain Friendly reputation with Cenarion Circle to be able to complete this quest.", progress = "It's in our best interest to keep our most loyal allies well geared, {name}.", completion = "Great work, {name}.  Please accept this on behalf of the Cenarion Circle.  You've certainly earned it, friend!", sourceObjectiveStatus = "unverified-source-field" }
quests[8549] = { id = 8549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs Peacebloom!", description = "It is said that every generation must face a defining trial. I fear the Ahn'Qiraj War will be the crucible in which our mettle is tested. So we prepare, and in so doing find what we are made of.\n\nI have volunteered to help the Horde by gathering as much peacebloom as possible, so that it can be made into potions for the war. I hope that you are here to lend me your aid. If so, then I need you to bring back to me a good quantity of the herb. Will you assist me, {class}?", sourceObjective = "Bring 20 Peacebloom to Herbalist Proudfeather at the Valley of Spirits in Orgrimmar.", progress = "Back so soon with the peacebloom, {class}?", completion = "And so our efforts push us that much closer to war. Thank you for your hard work in gathering this peacebloom {class}. I assure you that it will go to good use, and that your contribution has been noted {name}. Should you find yourself willing, please return to me again with more of the flowers. Until then, may the Earth Mother guide you.", sourceObjectiveStatus = "unverified-source-field" }
quests[8550] = { id = 8550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs More Peacebloom!", progress = "Hello again, {name}. I am glad that you wish to speak to me once more concerning our neverending need for peacebloom. The war effort continues, and with it our production of potions and elixirs to aid in the battles to come.\n\nWill you help us again, {class}? I am in need of the same amount of peacebloom as before, so if you can gather it up and return it to me here I would be most grateful. Of course, if you already have it on your person, I will be more than happy to accept it from you now.", completion = "Thank you for your continued efforts, {name}. You bring great honor to yourself and your ancestors with your selfless giving, and it will be known to all! I will store these herbs away so that they stay fresh until they are needed. Once again you reveal the truest spirit of the Horde, the struggle to overcome and the promise that we can work together to do so." }
quests[8551] = { id = 8551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captain's Chest", description = "I used to sail a ship from here all the way to Ratchet, in Kalimdor.  I was a successful captain with a sterling reputation.\n\nUntil...\n\nThose cursed sea giants ruined me!  They smashed my ship, killed my crew, and set me on a lifeboat to Booty Bay.  And one of the giants, Gorlash, stole my Captain's Chest.  He said he wanted it for a snuffbox.  The nerve!\n\nI hear Gorlash wanders the coast east of here.  Find him and get back my chest!  Do that, and you'll have earned a captain's gratitude.", sourceObjective = "Bring Smotts' Chest to Hecklebury Smotts in Booty Bay.", progress = "Ahoy, {name}!  Did you find Gorlash?  That chest was my favorite, and it has a hidden compartment that held my greatest treasures!", completion = "You found it!  Oh happy day, this is!  Thank you, {name}.  Getting back my chest cools some of the fire in me.\n\nBut my revenge isn't complete...", sourceObjectiveStatus = "unverified-source-field" }
quests[8552] = { id = 8552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Monogrammed Sash", description = "This fine sash has the letters \"HS\" embroidered along its hem.", sourceObjective = "Return the Monogrammed Sash to its owner.", progress = "Hello.  Do you have business with me?", completion = "You recovered my sash?  Then...you must have killed Mok'rash the sea giant!  Hooray!\n\nI'm glad the scurvy villain's dead - Mok'rash was one of three sea giants who smashed my ships and killed my crew.\n\nThree times.\n\nYou are a {class} of worth, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8553] = { id = 8553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captain's Cutlass", description = "After I lost my first ship to those giants, I bought another.  Named Smotts' Revenge, I filled it with supplies and crew, and set out to find the villains.  I found them, but...they beat me.  They smashed Smotts' Revenge, killed my second crew and set me on another lifeboat.\n\nThis time another of the giants, Negolash, stole my cutlass.\n\nFace Negolash and bring me my cutlass!\n\nSpeak with Sprogger.  He was my cook on the Smotts' Revenge, and survived the last attack.  He can help you find the giant.", sourceObjective = "Speak with Sprogger.", completion = "Hello hello, {name}.  Captain told me you're going after Negolash, eh?", sourceObjectiveStatus = "unverified-source-field" }
quests[8554] = { id = 8554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Facing Negolash", description = "Negolash is a hungry giant.\n\nWhen the giants destroyed our ship, Negolash went straight for my kitchen.  He wasn't hungry for crew like the other giants.  Negolash wanted wine...and my Barbecued Buzzard Wings.  They're my specialty, and I had to go all the way to the Badlands for the recipe!\n\nIf you want to lure the giant, then get some wine and a heap of buzzard wings.  Put them in our old lifeboat, southeast of here along the coast.  When Negolash smells all that food, he'll come for sure!", sourceObjective = "Bring 10 Barbecued Buzzard Wings and 5 bottles of Junglevine Wine to Captain Smotts' Lifeboat.\n\nKill Negolash, and bring Smotts' Cutlass to Captain Smotts in Stranglethorn.", progress = "Did you get my cutlass, {name}?", completion = "You got my cutlass from Negolash!  I can't believe my fortune, {name}!  Meeting you has turned my luck to the better, make no mistake there!\n\nThank you!  And if I ever get a new ship and you're looking to sail the seas, you would be my honored guest.", sourceObjectiveStatus = "unverified-source-field" }
quests[8555] = { id = 8555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Charge of the Dragonflights", sourceObjective = "Eranikus, Vaelastrasz, and Azuregos... No doubt you know of these dragons, mortal. It is no coincidence, then, that they have played such influential roles as watchers of our world.\n\nUnfortunately (and my own naivety is partially to blame) whether by agents of the Old Gods or betrayal by those that would call them friend, each guardian has fallen to tragedy. The extent of which has fueled my own distrust towards your kind.\n\nSeek them out... And {race}, prepare yourself for the worst.", sourceObjectiveStatus = "unverified-source-field" }
quests[8556] = { id = 8556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signet of Unyielding Strength", description = "The rings worn by the Qiraji lieutenants are rumored to grant them formidable abilities.  The corrupted gems that adorn them could, in theory, be swapped out with more pure materials to create uncorrupted versions of the rings.\n\nThe gems that adorn Qiraji idols would work quite well, as their quality is superior.\n\nBring me the ring and idols and I'll create a powerful ring for you, {class}.", sourceObjective = "Bring 1 Qiraji Magisterial Ring, 2 Lambent Idols, 5 Bronze Scarabs and 5 Ivory Scarabs to Windcaller Yessendra in Silithus. You must also attain Honored reputation with Cenarion Circle to complete this quest.", progress = "Did you bring me the ring and materials, {name}?", completion = "I will swap the gem on the ring for you.  You'll find the effect is much more... agreeable.", sourceObjectiveStatus = "unverified-source-field" }
quests[8557] = { id = 8557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drape of Unyielding Strength", description = "I'm glad to hear you're aiding us in our attack on Ahn'Qiraj, {name}.  I can make you a protective item that'll be of assistance in the fight against our enemy, {class}.\n\nI shall need a Qiraji drape, which I'll resize for you of course.  I'll also need idols and scarabs which I'll use to create a suitable clasp.\n\nI promise you won't be disappointed.", sourceObjective = "Bring 1 Qiraji Martial Drape, 2 Onyx Idols, 5 Silver Scarabs and 5 Bone Scarabs to Keyl Swiftclaw in Silithus. You must also obtain Revered reputation with Cenarion Circle to complete this quest.", progress = "Did you bring the materials for the cloak, {name}?", completion = "Ah yes... this drape is immaculate.\n\nTake this cloak, {name}.  May it protect you from the foul magic of the Qiraji.", sourceObjectiveStatus = "unverified-source-field" }
quests[8558] = { id = 8558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sickle of Unyielding Strength", description = "The Qiraji and their servants wield items made with the rarest and finest materials: bones from gargantuan ancient creatures, gems from the depths of the earth, metals pure and strong.\n\nJust the sight of Qiraji artifacts fills me with an urge to practice my craft with their shattered and smelted pieces.  Prove your allegiance to the Circle, {name}, and I will make you a powerful weapon from the finest Qiraji materials.", sourceObjective = "Bring 1 Qiraji Spiked Hilt, 2  Alabaster Idols, 5 Crystal Scarabs and 5 Stone Scarabs to Warden Haro in Silithus. You must also attain Exalted reputation with Cenarion Circle to complete this quest.", progress = "Did you bring me the components I require, {name}?", completion = "You've done well, {class}.  This is a masterwork hilt... the balance is perfect.\n\nTake your weapon, {name}.  Wield it with great confidence and vanquish our enemies!", sourceObjectiveStatus = "unverified-source-field" }
quests[8559] = { id = 8559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conqueror's Greaves", description = "Qiraji magic is strong and ancient.  The most powerful qiraji wield items of such might, they'd give pause even to a dragon.\n\nBring me the qiraji bindings of command and other minor components by and I'll create a set of powerful boots for you.\n\nYou will find them useful in the fight against the enemy.", sourceObjective = "Bring the Qiraji Bindings of Command, 2 Idols of War, 5 Ivory Scarabs and 5 Gold Scarabs to Kandrostrasz in Ahn'Qiraj. This quest also requires Neutral faction with the Brood of Nozdormu.", progress = "You've acquired the items I requested, {name}?", completion = "You've done well, {name}.  You've proven you're no ordinary mortal.\n\nI give you these with the confidence they'll aid you in crushing the vile qiraji.", sourceObjectiveStatus = "unverified-source-field" }
quests[8560] = { id = 8560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conqueror's Legguards", description = "You seek to prove your worth to my kind, mortal?  Very well, perhaps we can be of mutual assistance.\n\nThe ancient sandworm, Ouro, is a being of legendary power.  He is rumored to have been created by the Old God himself as a mockery of life.\n\nHis skin is unnatural... thick, nearly impregnable, yet it's flexible and allows him to move with the speed and grace of a much smaller creature.\n\nBring me a sample of his skin along with other minor components and I shall craft you leggings of great power.", sourceObjective = "Bring Ouro's Intact Hide, 2 Idols of Death, 5 Bronze Scarabs and 5 Ivory Scarabs to Kandrostrasz inside Ahn'Qiraj. You must also attain Friendly reputation with the Brood of Nozdormu to complete this quest.", progress = "Did you bring the components I require, {name}?", completion = "Yes... the worm's hide will make for an excellent protective layer.  Combined with the strongest parts from the Qiraji we've destroyed on our way here, this should make for a formidable piece of armor.  May it aid you in facing the unspeakable horrors that await inside!", sourceObjectiveStatus = "unverified-source-field" }
quests[8561] = { id = 8561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conqueror's Crown", description = "The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity.  They mock me, knowing I cannot step further into their domain to save my brother Arygos.\n\nIn my visions I see their monstrous faces adorned by powerful crowns.  But I will have my revenge... I will transmute these symbols of Qiraji power to ones better suited to our needs.\n\nBring me the components I require, {name}.  I will give you a headpiece of unmatched power.", sourceObjective = "Bring Vek'nilash's Circlet, 2 Idols of the Sun, 5 Stone Scarabs and 5 Crystal Scarabs to Andorgos in Ahn'Qiraj. You must also attain Friendly reputation with the Brood of Nozdormu to complete this quest.", progress = "Did you bring me the components I asked for, {name}?", completion = "You've succeeded!  The whispers from the Twin Emperors have ceased.\n\nTake this as a reward.  The mere sight of it will strike fear in the hearts of the Qiraji... it shall remind them of their fallen leaders and of the mortal that slew them.", sourceObjectiveStatus = "unverified-source-field" }
quests[8562] = { id = 8562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conqueror's Breastplate", description = "The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj.  The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power.\n\nWhen the stars are favorable, he will lash out against all living beings with terrible wrath.  You must find him before then and find a way to bring his existence to an end.\n\nDo this and bring me a piece of his husk.  I shall grant you armor no mortal has ever worn... armor fit for one who has slain a god!", sourceObjective = "Bring the Carapace of the Old God, 2 Idols of War, 5 Silver Scarabs and 5 Bone Scarabs to Vethsera inside Ahn'Qiraj. You must also attain Honored reputation with the Brood of Nozdormu to complete this quest.", progress = "At his dwelling in Ahn'Qiraj, dread C'Thun awaits in slumber.", completion = "I did not expect you to return from your attempt, {name}.\n\nYou've fulfilled a destiny greater than that of most immortal beings.\n\nBy slaying C'Thun you've not only saved all of Azeroth, you've also tipped the scales of cosmic events beyond your comprehension.\n\nAccept this breastplate as a symbol of the glory and burden that will come as a consequence of your actions.\n\nMay its power aid you in the challenges that await you, god-slayer!", sourceObjectiveStatus = "unverified-source-field" }
quests[8563] = { id = 8563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warlock Training", description = "As you advance within your class, you will want to take advantage of the training that your class trainer can provide you.  For young warlocks here on Sunstrider Isle, your trainer is Summoner Teli'Larien.  Speak with Summoner Teli'Larien and see what training he has available for you.  The things he will teach do have a cost, so bring some coin with you.\n\nYour trainer - as with all the trainers on Sunstrider Isle - is inside the Sunspire on the lower level.", sourceObjective = "Speak with Summoner Teli'Larien - the Warlock class trainer - inside the Sunspire on Sunstrider Isle.", completion = "{name} - your name has passed my ears as one seeking out a master in the ways of the {class}.  You look capable enough, but I seek more than just looks from my students.  You must be ready to delve where others fear to look to gain your power.  I will teach you, but I will not tolerate failure.\n\nThere will be monetary costs associated with your training, but you should be more concerned with the cost your mind is willing to make.  If you are ready, we shall begin.", sourceObjectiveStatus = "unverified-source-field" }
quests[8564] = { id = 8564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priest Training", description = "As you advance within your class, you will want to take advantage of the training that your class trainer can provide you.  For young priests here on Sunstrider Isle, your trainer is Matron Arena.  Speak with the matron and see what training she has available for you.  The things she will teach do have a cost, so bring some coin with you.\n\nMatron Arena - as with all the trainers on Sunstrider Isle - is inside the Sunspire on the lower level.", sourceObjective = "Speak with Matron Arena - the Priest class trainer - inside the Sunspire on Sunstrider Isle.", completion = "Welcome, {name} - I am Matron Arena.  I offer my services to those who seek to learn the ways of the {class}.  Such a path is often misconstrued as a path of pacifism; for we blood elves, this couldn't be further from the truth.  While we do mend both bone and spirit, we also act as a fist of vengeance for those who would transgress against us.\n\nI will train you, but all I ask is that you cover any training costs that may come up, and that you learn with an open mind.  If you agree to this, we may begin.", sourceObjectiveStatus = "unverified-source-field" }
quests[8565] = { id = 8565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Past Victories in Arathi" }
quests[8566] = { id = 8566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Past Victories in Arathi" }
quests[8567] = { id = 8567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Past Victories in Warsong Gulch" }
quests[8568] = { id = 8568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Past Victories in Warsong Gulch" }
quests[8569] = { id = 8569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Past Efforts in Warsong Gulch" }
quests[8570] = { id = 8570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Past Efforts in Warsong Gulch" }
quests[8572] = { id = 8572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veteran's Battlegear", description = "The badges you collect from performing combat, logistics and tactical assignments for Cenarion Hold are more than just for show, {name}.\n\nYou'd be wise to hold on to them.  As you prove your loyalty to our organization I can offer you some of the gear we reserve for our closest allies in exchange for those badges.", sourceObjective = "Bring 7 Cenarion Combat Badges, 4 Cenarion Logistics Badges and 4 Cenarion Tactical Badges to Vargus at Cenarion Hold in Silithus. You must also attain Honored reputation with Cenarion Circle to be able to complete this quest.", progress = "It's in our best interest to keep our most loyal allies well geared, {name}.", completion = "Great work, {name}.  Please accept this on behalf of the Cenarion Circle.  You've certainly earned it, friend!", sourceObjectiveStatus = "unverified-source-field" }
quests[8573] = { id = 8573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion's Battlegear", description = "The badges you collect from performing combat, logistics and tactical assignments for Cenarion Hold are more than just for show, {name}.\n\nYou'd be wise to hold on to them.  As you prove your loyalty to our organization I can offer you some of the gear we reserve for our closest allies in exchange for those badges.", sourceObjective = "Bring 15 Cenarion Combat Badges, 20 Cenarion Logistics Badges, 20 Cenarion Tactical Badges and 1 Mark of Cenarius to Vargus at Cenarion Hold in Silithus. You must also attain Exalted reputation with Cenarion Circle to be able to complete this quest.", progress = "It's in our best interest to keep our most loyal allies well geared, {name}.", completion = "Great work, {name}.  Please accept this on behalf of the Cenarion Circle.  You've certainly earned it, friend!", sourceObjectiveStatus = "unverified-source-field" }
quests[8574] = { id = 8574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stalwart's Battlegear", description = "The badges you collect from performing combat, logistics and tactical assignments for Windcaller Proudhorn are more than just for show, {name}.\n\nYou'd be wise to hold on to them.  As you prove your loyalty to our organization I can offer you some of the gear we reserve for our closest allies in exchange for those badges.", sourceObjective = "Bring 15 Cenarion Combat Badges, 20 Cenarion Logistics Badges, 17 Cenarion Tactical Badges and 1 Mark of Remulos to Vargus at Cenarion Hold in Silithus. You must also attain Revered reputation with Cenarion Circle to be able to complete this quest.", progress = "It's in our best interest to keep our most loyal allies well geared, {name}.", completion = "Great work, {name}.  Please accept this on behalf of the Cenarion Circle.  You've certainly earned it, friend!", sourceObjectiveStatus = "unverified-source-field" }
quests[8575] = { id = 8575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azuregos's Magical Ledger", description = "You cannot understand a single word on this ledger. You don't even know what language it is written in!", sourceObjective = "Deliver Azuregos's Magical Ledger to Narain Soothfancy in Tanaris.", progress = "Ooooh! Magical pulsing thingy! For me?", completion = "<Narain eagerly examines the letter.>\n\nOutstanding, {race}! What is it? I can't read a lick of Draconic.", sourceObjectiveStatus = "unverified-source-field" }
quests[8576] = { id = 8576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Translating the Ledger", sourceObjective = "First things first, {name}! We need to figure out what Azuregos wrote in this ledger.\n\nYou say that he's told you to make an arcanite buoy and that this is the schematic? Strange that he would write this in Draconic. That old goat knows I can't read this nonsense.\n\nIf this is going to work, I'm going to need my scrying goggles, a five hundred pound chicken and volume II of \"Draconic for Dummies.\" Not necessarily in that order.", sourceObjectiveStatus = "unverified-source-field" }
quests[8577] = { id = 8577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stewvul, Ex-B.F.F.", description = "If I am to translate anything, I will need my scrying goggles. Unfortunately, those were stolen quite some time ago by my ex-best friend forever, Stewvul. He broke my heart in five places and then left me here to rot.\n\nWith the help of my trusty crystal ball, I've isolated his whereabouts to either the Greymane Wall in Silverpine or what appears to be a portal world in the Outland that is currently being overrun by the Burning Legion. You're going to have to track him down and get my goggles back, {name}!", sourceObjective = "Narain Soothfancy wants you to find his ex-best friend forever (BFF), Stewvul, and take back the scrying goggles that Stewvul stole from him.", completion = "I can't believe he found me. I thought for sure that I'd lost him when I was in the Outland. I'm not going back there, {race}! No way, no how! I'm through being his part time best friend forever and full time slave.", sourceObjectiveStatus = "unverified-source-field" }
quests[8578] = { id = 8578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scrying Goggles? No Problem!", description = "<You hear a sigh of relief escape the crate.>\n\nYou just want his scrying goggles? Great! That will be no problem... Just give me a minute to... Hey! Where the... Dagnabbit!\n\nWell, there's some bad news and some worse news. The bad news is that I lost the goggles. The worse news is that I lost them when I was nosing around in the Molten Core last month. Yep, the Molten Core... I guess that concludes our business! Bye!", sourceObjective = "Find Narain's Scrying Goggles and return them to Narain Soothfancy in Tanaris.", progress = "The Molten Core, eh? I hope my goggles are still in one piece!", completion = "Outstanding! Now where did I put that 500 pound chicken and Volume II of \"Draconic For Dummies???\" Oh, and here's a little something for all your hard work!", sourceObjectiveStatus = "unverified-source-field" }
quests[8579] = { id = 8579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mortal Champions", progress = "We sense the presence of our enslaved brethren deeper inside Ahn'Qiraj; yet not even an army of dragons would be enough to rescue them, {race}.\n\nThe same spell that imprisoned them would place us firmly under C'Thun's control should we come any closer to him.\n\nThe Old God has foreseen our arrival.  All hope is lost.  What difference could a mere mortal like you possibly make?", completion = "I see that you're no ordinary mortal, {name}.  Your chances against the Old God, however infinitely small, are greater than ours at this point.  After all, while he expects dragons at his doorstep, he is not prepared for someone like you.\n\nJust as Anachronos and Staghelm defeated the Qiraji a thousand years ago through the alliance of mortal and dragon races, we too shall form a pact.  Gain the trust of the Bronze Dragonflight and you'll gain our trust.  Only then we shall make a true champion out of you." }
quests[8580] = { id = 8580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs Firebloom!", description = "Hey, {class}. Ya you, mon! There be a whole mess of firebloom the Horde thinkin' they need for this Ahn'Qiraj war effort. Maybe they put it in nice things that go boom? Maybe they give it to the Alliance as fuel for their steam tanks? Who knows? Not Pele'keiki!\n\nPele'keiki know this though... he know you gonna help him out and bring back lots of the firebloom, right, mon?", sourceObjective = "Bring 20 Firebloom to Batrider Pele'keiki at the Valley of Spirits in Orgrimmar.", progress = "You not want to make Pele'keiki mad. You make Pele'keiki happy by bringing him lots of firebloom, real soon.", completion = "{class}! Pele'keiki happy for now. Pele'keiki take all that firebloom and put it in box so it stay fresh. Pele'keiki be seein' to it that all the firebloom bein' made into good stuff for the war. And if you be gettin' anymore, you come see Pele'keiki fast. Pele'keiki prolly be needin' more.", sourceObjectiveStatus = "unverified-source-field" }
quests[8581] = { id = 8581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs More Firebloom!", progress = "Pele'keiki know you come to help. Bring many firebloom and make him very happy. Pele'keiki might make big bombs with firebloom. Drop them on insects from his bat over Ahn'Qiraj when war come. But Pele'keiki need more firebloom, {class}!\n\nYou gonna bring Pele'keiki that firebloom, real quick now. Come back with at least as much as last time, and Pele'keiki be pleased.", completion = "This no joke, {class}? You bring Pele'keiki firebloom that fast? Pele'keiki count them up right now, mon! You makin' Pele'keiki so happy, he be tellin' everyone, {name} best firebloom collector ever! Pele'keiki can't wait for war to start. Now we really light up the sky over Silithus, right, bruddah?!" }
quests[8582] = { id = 8582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs Purple Lotus!", description = "The purple lotus, {class}, is a reagent in a great many potions, elixirs and oils, some of which will be of use to us at Ahn'Qiraj. We're going to need to create an immense number of those potions for the war effort. And I'm going to experiment to find more uses for the lotus as well. But to do all of that I'm going to need a great quantity of the flower.\n\nThat's where you come in. Go out into the field and collect up as many purple lotuses as you can. Is this something that you are willing to do for us?", sourceObjective = "Bring 20 Purple Lotus to Apothecary Jezel at the Valley of Spirits in Orgrimmar.", progress = "Returned already with the purple lotus that I have requested, {class}? It is critical that you do so in as timely as fashion as possible lest all that I am attempting here come to naught.", completion = "A commendable effort, {class}. I will measure these specimens for their appropriate usage and note your contribution. The purple lotus will then need to be properly stored until I am ready for them. As for you, if you are still available I should imagine that I'll still need more purple lotus. Please check back with me in a moment.", sourceObjectiveStatus = "unverified-source-field" }
quests[8583] = { id = 8583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs More Purple Lotus!", progress = "In fact it does appear that we are in need of even more purple lotus, {class}. While my own studies have yet to determine a new useful application for the herb, there are tried and true methodologies yet to be employed.\n\nI need you to once again go out into the field and collect at least twenty purple lotus samples. Return them to me here.", completion = "Excellent and precise work, {name}. Your diligence is to be commended, as is your celerity. I will personally see to it that none of these purple lotus go to waste.\n\nThank you again, and should you come by more purple lotus do not hesitate to bring them to me with utmost haste." }
quests[8584] = { id = 8584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never Ask Me About My Business", description = "If there is one thing that you should know about me, it is this: NEVER ask me about my business! I work with things you simply cannot understand. Like for example: Do you know what a psychotronic muzzledorf is? Of course you don't! And that's why we leave the planning to me and the fetching to you.\n\nAs I said earlier, if this is going to work, we're going to need a 500 pound chicken.\n\nHead to Gadgetzan and speak with Dirge Quikcleave - he'll get you started on finding a suitable specimen.", sourceObjective = "Narain Soothfancy in Tanaris wants you to speak with Dirge Quikcleave in Gadgetzan.", completion = "<Dirge scratches his head.>\n\nA 500 pound chicken? There's no such thing! Not anymore, at least. I knew of such a chicken... The Black Chicken of Death...\n\n<Dirge's voice trails off.>\n\nBut yes, nobody ever saw that chicken and lived to tell the tale. I've got an idea that could benefit the both of us, kid.", sourceObjectiveStatus = "unverified-source-field" }
quests[8585] = { id = 8585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Isle of Dread!", description = "Legend has it that the chimaerok of the Isle of Dread in Feralas have the most succulent and tender vittles in existence! Now these chimaerok also have a daddy who, with proper preparation, may or may not look like a 500 pound chicken.\n\nHead to the Isle of Dread and kill Lord Lakmaeran and bring me his fresh carcass. That should satisfy the gnome. To satisfy me, you'll need to get your hands on some chimaerok tenderloin.\n\nDo this and you'll have your 500 pound chicken and a little something extra.", sourceObjective = "Recover Lakmaeran's Carcass and 20 Chimaerok Tenderloins for Dirge Quikcleave in Tanaris.", progress = "Mmmmm... Chimaerok...", completion = "Look at the marbleization on those tenderloins! Fantastic!\n\nNow about that chicken... Hrm, let me see. I'm going to need a few minutes to devise the recipe.", sourceObjectiveStatus = "unverified-source-field" }
quests[8586] = { id = 8586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dirge's Kickin' Chimaerok Chops", description = "My recipe is complete! What I need from you now is some rocket fuel and deeprock salt. I'll handle the spices and the meat you brought me will cover the rest.\n\nAfter you bring me what I asked for, the chicken will be ready to take back to Narain.", sourceObjective = "Dirge Quikcleave in Gadgetzan wants you to bring him 20 Goblin Rocket Fuel and 20 Deeprock Salt.", progress = "Hurry it up, kid. We don't want this meat to go bad.", completion = "It's ready! I present to you my greatest creation: Dirge's Kickin' Chimaerok Chops!", sourceObjectiveStatus = "unverified-source-field" }
quests[8587] = { id = 8587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Narain", description = "I'm a goblin of my word, kid. Here's your 500 pound chicken.\n\nWhat a gnome wants with a 500 pound chicken, I'll never know...\n\n<Dirge grumbles something unintelligible.>\n\nProbably to sleep in it... Dirty gnomes...", sourceObjective = "Deliver the 500 Pound Chicken to Narain Soothfancy in Tanaris.", progress = "What is that scrumptious smell?", completion = "<Narain mashes two fists into the huge chicken, stuffing his face full of Dirge's delicious delicacy.>\n\nMMmmm... This is unbelievable! Best chicken I've ever had!", sourceObjectiveStatus = "unverified-source-field" }
quests[8588] = { id = 8588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs Heavy Leather!", description = "Since we're preparing for war, it might be best if we get all of the goods we need first, don't you think, mon? One of the staples of the war materiel that we're producing is heavy leather. We'll use it for just about everything, from reinforcement to armor, and good old plain tarps too.\n\nBut first we need to get our hands on more of it. That's your job, {class}. Sharpen your knife and bring me back a bundle. Then we'll talk further.", sourceObjective = "Bring 10 Heavy Leather to Skinner Jamani at the Valley of Spirits in Orgrimmar.", progress = "I've got no time for games if you're just here to jibber-jabber, {class}. There are too many stacks of heavy leather that need curing. Come back when you have at least ten for me.", completion = "Oh, so you do have the heavy leather I needed. Your blade is sharp indeed, {class}; these are good skins! Now that we've gotten off on the right foot with one another I'll make sure that your contribution is put to good use. And if you happen to come across more heavy leather, bring it my way.", sourceObjectiveStatus = "unverified-source-field" }
quests[8589] = { id = 8589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs More Heavy Leather!", progress = "It's true, {class}, I still need more heavy leather. The requests from the generals and their quartermasters seem endless. And that's nothing compared to what the zeppelin masters are asking for!\n\nI need to get my quota collected on the double. {name}, bring me more stacks of heavy leather as soon as you can!", completion = "You da mon, mon! Thank you so much for the heavy leather. Every little bit gets us that much closer. I'll just get these onto a pile so that the other leatherworkers can get to work on them.\n\nThanks again, {name}, and if you come across more stacks of heavy leather, you know where you can find me." }
quests[8590] = { id = 8590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs Thick Leather!", description = "I'm glad that you decided to speak to me about this, {class}. It looks like the Horde's preparations for the upcoming Ahn'Qiraj War are in full swing. But you and I still need to do our part.\n\nI've been asked to collect a great number of thick leather skins for use in all manner of war materiel, and I need you to help me by going out there and gathering them up. There's honor and the gratitude of the Horde in it for you should you decide to help. Will you?", sourceObjective = "Bring 10 Thick Leather to Sergeant Umala at the Valley of Spirits in Orgrimmar.", progress = "{class}, have you returned so soon with the ten thick leather that we discussed?", completion = "Good work, {class}. I'm sure that these thick leather skins will be put to use reinforcing zeppelins and making all manner of armor and weaponry. You have my thanks, and that of the Horde. Come back again if you come across more thick leather in your travels, and luck be with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[8591] = { id = 8591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs More Thick Leather!", progress = "{class}, as you can see I still need to gather up more thick leather. Once again I ask your help with this task, and promise that if you complete it, you will be recognized for your efforts.\n\nTime is of the essence! Return to me with the thick leather so that we can finish our preparations and go to war, hero!", completion = "You did it, {name}, I knew that you would! Once again, thank you on behalf of the entire Horde. Your efforts have been noted and are greatly appreciated. And if you find yourself with more thick leather that you'd like to donate, bring them to me here.\n\nLok'tar Ogar, {class}!" }
quests[8592] = { id = 8592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiara of the Oracle", description = "The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity.  They mock me, knowing I cannot step further into their domain to save my brother Arygos.\n\nIn my visions I see their monstrous faces adorned by powerful crowns.  But I will have my revenge... I will transmute these symbols of Qiraji power to ones better suited to our needs.\n\nBring me the components I require, {name}.  I will give you a headpiece of unmatched power.", sourceObjective = "Bring Vek'nilash's Circlet, 2 Idols of the Sage, 5 Silver Scarabs and 5 Bone Scarabs to Andorgos in Ahn'Qiraj. You must also attain Friendly reputation with the Brood of Nozdormu to complete this quest.", progress = "Did you bring me the components I asked for, {name}?", completion = "You've succeeded!  The whispers from the Twin Emperors have ceased.\n\nTake this as a reward.  The mere sight of it will strike fear in the hearts of the Qiraji... it shall remind them of their fallen leaders and of the mortal that slew them.", sourceObjectiveStatus = "unverified-source-field" }
quests[8593] = { id = 8593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trousers of the Oracle", description = "You seek to prove your worth to my kind, mortal?  Very well, perhaps we can be of mutual assistance.\n\nThe ancient sandworm, Ouro, is a being of legendary power.  He is rumored to have been created by the Old God himself as a mockery of life.\n\nHis skin is unnatural... thick, nearly impregnable, yet it's flexible and allows him to move with the speed and grace of a much smaller creature.\n\nBring me a sample of his skin along with other minor components and I shall craft you leggings of great power.", sourceObjective = "Bring Ouro's Intact Hide, 2 Idols of Life, 5 Gold Scarabs and 5 Clay Scarabs to Kandrostrasz inside Ahn'Qiraj. You must also attain Friendly reputation with the Brood of Nozdormu to complete this quest.", progress = "Did you bring the components I require, {name}?", completion = "Yes... the worm's skin will make for an excellent protective layer.  Combined with the strongest parts from the Qiraji we've destroyed on our way here, this should make for a formidable piece of armor.  May it aid you in facing the unspeakable horrors that await inside!", sourceObjectiveStatus = "unverified-source-field" }
quests[8594] = { id = 8594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mantle of the Oracle", description = "It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon.\n\nBring me the bindings worn by the highest Qiraji leaders and I shall shape them into a set of pauldrons more dreadful than even the wings of Nefarian himself!", sourceObjective = "Bring the Qiraji Bindings of Command, 2 Idols of Rebirth, 5 Silver Scarabs and 5 Ivory Scarabs to Andorgos in Ahn'Qiraj. You must also attain Neutral reputation with the Brood of Nozdormu to complete this quest.", progress = "Have you collected the components I require?", completion = "From the materials you bring and from the scales of our fallen Qiraji foes I make you these pauldrons, mortal.  May they grant you the protection you need and may the sight of them strike fear into our enemies.", sourceObjectiveStatus = "unverified-source-field" }
quests[8595] = { id = 8595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mortal Champions", progress = "Killing one Qiraji lord is a notable accomplishment for a mortal, {name}.  They are however, numerous and powerful.  Continue to defeat them to prove your worth as our champion.", completion = "You continue to serve us well, {name}.  Our pact remains in place." }
quests[8596] = { id = 8596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Footwraps of the Oracle", description = "Qiraji magic is strong and ancient.  The most powerful qiraji wield items of such might, they'd give pause even to a dragon.\n\nBring me the qiraji bindings of command and other minor components by and I'll create a set of powerful boots for you.\n\nYou will find them useful in the fight against the enemy.", sourceObjective = "Bring the Qiraji Bindings of Command, 2 Idols of Death, 5 Bronze Scarabs and 5 Gold Scarabs to Kandrostrasz in Ahn'Qiraj. This quest also requires Neutral faction with the Brood of Nozdormu.", progress = "You've acquired the items I requested, {name}?", completion = "You've done well, {name}.  You've proven you're no ordinary mortal.\n\nI give you these with the confidence they'll aid you in crushing the vile qiraji.", sourceObjectiveStatus = "unverified-source-field" }
quests[8597] = { id = 8597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draconic for Dummies", description = "I knew that book would come in handy some day! Thankfully, I had the wit and foresight to stow it somewhere safe.\n\nDon't worry, it's in a place that nobody could ever hope to find it! I needed a gyrocopter just to get there the first time. Unfortunately I crashed it on the beach on my way back. It was through that accident that I gained these super-gnomish psychic powers!\n\nLook for my crashed gyrocopter somewhere on Land's End Beach and swim south from there! You'll know the spot when you see it!", sourceObjective = "Find Narain Soothfancy's book, buried on an island in the South Seas.", completion = "The book is gone! On top of the dirt mound is a note.", sourceObjectiveStatus = "unverified-source-field" }
quests[8598] = { id = 8598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "rAnS0m", description = "<The text on this note is made up of various typefaces glued onto the parchment's surface.>\n\nWe've got your precious book, gnome. If you ever want to see it again, you'll do exactly as we ask.\n\n<A detailed set of instructions is listed, spanning 3 pages.>\n\nBring the money and come alone!", sourceObjective = "Return the Ransom Letter to Narain Soothfancy in Tanaris.", progress = "Say, what's the matter?", completion = "<Narain's face glows a bright red.>\n\nBooknap my... book, will they!? I'll teach them what it means to mess with a psychic gnome!", sourceObjectiveStatus = "unverified-source-field" }
quests[8599] = { id = 8599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Love Song for Narain", description = "It isn't often that I get visitors. As a matter of fact, the last time I had a visitor was when I rescued that dear, sweet gnome from the wreckage of the crashed flying machine.\n\n<Meridith gazes into nothingness, lost in a memory.>\n\nDo you know him? Narain? Narain Soothfancy? Oh it would mean so much to me if somebody would deliver a message to him for me. I must tell him how I feel! I know it's love! I just know it!\n\nCould you possibly deliver a message to Narain? I would be forever indebted to you!", sourceObjective = "Take Meridith's Love Letter to Narain Soothfancy in Tanaris.", progress = "You smell like fish!", completion = "What!?\n\n<Narain starts to fidget.>\n\nWell, um... What do you want me to do??? She's a fish! A FISH I tell you! And I'm a gnome. It could never work out.", sourceObjectiveStatus = "unverified-source-field" }
quests[8600] = { id = 8600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs Rugged Leather!", description = "I find that the fit of the knife in your palm is more important than the edge on it. Even the dullest blade can be made to cut if pressure is being properly applied through it, wouldn't you agree, {class}? But you and I don't have such problems as we maintain the sharpest of edges, yes? \n\nWell, no matter, I have a task for you. In service to the Horde, and to do your part for the Ahn'Qiraj war effort, I want you to return to me with a number of rugged leather skins. This is something that you will do, no?", sourceObjective = "Bring 10 Rugged Leather to Doctor Serratus at the Valley of Spirits in Orgrimmar.", progress = "It couldn't possibly be taking you this long to slice off ten rugged leather for me! Perhaps you should sharpen your skinning knife? Or, perhaps I am mistaken and you have them there in your pack?", completion = "Very well, it appears you've done a fairly decent job of it, though some of those skins look a bit ragged about the edges. No matter, the task is completed, and you have earned your reward. Should you come across another stack of rugged leather, be sure to bring them to me posthaste.", sourceObjectiveStatus = "unverified-source-field" }
quests[8601] = { id = 8601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs More Rugged Leather!", progress = "Preparations for the impending war at Ahn'Qiraj are proceeding, {class}. However, to ensure that we do not fall behind, or at least that I am not the one that causes us to fall behind, I want for you to bring back another stack of rugged leather. Your prompt attention to this matter will be greatly appreciated, {name}.", completion = "Practice, practice, practice. A well honed knife and the skill to use it will get you far in this world, {name}. Looks like the edges on these skins are better than the last. Did you buy a new knife?\n\nIn any case, we thank you for your efforts. Your donation has been noted, and will be put to good use I can assure you. Should you find yourself in the possession of more rugged leather, be sure to come back and speak with me, as I will probably need it." }
quests[8602] = { id = 8602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormcaller's Pauldrons", description = "It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon.\n\nBring me the bindings worn by the highest Qiraji leaders and I shall shape them into a set of pauldrons more dreadful than even the wings of Nefarian himself!", sourceObjective = "Bring the Qiraji Bindings of Dominance, 2 Idols of Life, 5 Gold Scarabs and 5 Crystal Scarabs to Andorgos in Ahn'Qiraj. You must also attain Neutral reputation with the Brood of Nozdormu to complete this quest.", progress = "Have you collected the components I require?", completion = "From the materials you bring and from the scales of our fallen Qiraji foes I make you these pauldrons, mortal.  May they grant you the protection you need and may the sight of them strike fear into our enemies.", sourceObjectiveStatus = "unverified-source-field" }
quests[8603] = { id = 8603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vestments of the Oracle", description = "The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj.  The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power.\n\nWhen the stars are favorable, he will lash out against all living beings with terrible wrath.  You must find him before then and find a way to bring his existence to an end.\n\nDo this and bring me a piece of his husk.  I shall grant you armor no mortal has ever worn... armor fit for one who has slain a god!", sourceObjective = "Bring the Husk of the Old God, 2 Idols of Death, 5 Stone Scarabs and 5 Crystal Scarabs to Vethsera inside Ahn'Qiraj. You must also attain Honored reputation with the Brood of Nozdormu to complete this quest.", progress = "At his dwelling in Ahn'Qiraj, dread C'Thun awaits in slumber.", completion = "I did not expect you to return from your attempt, {name}.\n\nYou've fulfilled a destiny greater than that of most immortal beings.\n\nBy slaying C'Thun you've not only saved all of Azeroth, you've also tipped the scales of cosmic events beyond your comprehension.\n\nAccept these vestments as a symbol of the glory and burden that will come as a consequence of your actions.\n\nMay their power aid you in the challenges that await you, god-slayer!", sourceObjectiveStatus = "unverified-source-field" }
quests[8604] = { id = 8604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs Wool Bandages!", description = "Greetings, {class}. In preparation for the war at Ahn'Qiraj, I am here coordinating the Horde's efforts at gathering wool bandages. Unfortunately, out in the field, our soldiers cannot afford to rely upon the presence of a healer to keep them alive. Trust me, I know first hand. Thus, we're putting together all of these first aid kits for them.\n\nIf you have the time, I need many wool bandages. Return them to me here and I will see to it that you are properly rewarded.", sourceObjective = "Bring 20 Wool Bandages to Healer Longrunner at the Valley of Spirits in Orgrimmar.", progress = "Ah, {class}, have you returned so quickly with the wool bandages?", completion = "You have my thanks, {class}, and the gratitude of the Horde. If you come across more wool bandages bring them to me here should you wish to further contribute to the war effort. Until then, may your ancestors watch over you!", sourceObjectiveStatus = "unverified-source-field" }
quests[8605] = { id = 8605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs More Wool Bandages!", progress = "Good to see you again, {class}. We are still working on preparations here for the war effort, and I can still use all of the help that you can give in gathering up wool bandaging. Any assistance at all will be greatly appreciated. I only hope that our efforts will be good enough. I've lost too many noble souls on the battlefields of yesterday to not do everything in my power to see to it that doesn't happen again.", completion = "You are an honorable {class}, {name}! I will see to it that these bandages get into the right hands. You have my thanks, and that of the Horde.\n\nGo in peace, and return to me again should you find yourself with excess wool bandaging. We can use all of the help that we can get here." }
quests[8606] = { id = 8606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decoy!", description = "I've got it! Here's what we're going to do. I'm going to fill a sack up with rocks and you're going to make the drop. I know it said that I should make the delivery and I'm going to - sort of.\n\n<Narain looks you up and down.>\n\nYes, you will do just fine. Take this turban, robe, and sack of rocks and head to the drop off point in Winterspring.\n\nI've included everything you need in this special kit. When they show up to pick up the goods, snuff them out! That will teach them to mess with Narain!", sourceObjective = "Narain Soothfancy in Tanaris wants you to travel to Winterspring and place the Bag of Gold at the drop off point documented by the booknappers.", progress = "Hurry, {name}! Who knows what sick and twisted plans they have for my book!", completion = "I think we may have underestimated these booknappers.", sourceObjectiveStatus = "unverified-source-field" }
quests[8607] = { id = 8607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs Mageweave Bandages!", description = "I trust that you are speaking to me because you are going to help with the collection I have been entrusted to? Good! By whatever means, and I do mean whatever, I wish for you to gather up a good number of mageweave bandages. Fresh would be nice, but not absolutely necessary. Return them to me here, {class}, and I will personally see to it that you are properly rewarded.", sourceObjective = "Bring 20 Mageweave Bandages to Lady Callow at the Valley of Spirits in Orgrimmar.", progress = "Do not fail and make me look bad, {class}! Return here as quickly as possible with the mageweave bandages we discussed.", completion = "Surprising, yet acceptable. Perhaps I underestimated your 'abilities', {class}. Perhaps. You completed a very simple task, and for doing so you are to be rewarded out of proportion. But don't let it go to your head. If you really want to prove yourself you should get out there and bring me another bundle of mageweave bandages.", sourceObjectiveStatus = "unverified-source-field" }
quests[8608] = { id = 8608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs More Mageweave Bandages!", progress = "You returned? Interesting. As you can see I am still collecting for the Ahn'Qiraj 'war effort'. Which means that I need you to once again go out and collect a stack of mageweave bandages for me. I look forward to your return, {class}.", completion = "Astounding, {class}, you actually did it again! Well, they do say that I have good taste in those that I choose to place in my service. Very well, your contribution is noted and you will receive the social benefits that your efforts have afforded. I suggest though that you go back out and gather yet another bundle of mageweave bandages if you truly wish to prove your worth." }
quests[8609] = { id = 8609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs Runecloth Bandages!", description = "It appears inevitable that the Horde and Alliance are on a collision course for war at Ahn'Qiraj. Surprisingly, it is not a war with each other, but rather with the silithid, and whatever force controls them. Also surprisingly, both sides are doing their part to gather the resources necessary to wage a successful war.\n\nI am collecting runecloth bandages to distribute to the soldiers, but I won't be successful without assistance, hopefully yours. Is this something that you can aid me with, {class}?", sourceObjective = "Bring 20 Runecloth Bandages to Stoneguard Clayhoof at the Valley of Spirits in Orgrimmar.", progress = "The war comes soon, I think, {class}. I thank you for your time and effort devoted to helping with our gathering tasks. Do you return because you have obtained the runecloth bandages that we spoke of before?", completion = "You are a credit to the Horde, {class}. Thank you for your efforts; they are appreciated! I'll have to pack these fresh bandages away and take another count to see how far along we are to our goal. If you'd like you could gather more runecloth bandages and return them to me here.", sourceObjectiveStatus = "unverified-source-field" }
quests[8610] = { id = 8610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs More Runecloth Bandages!", progress = "Ever does the time grow nearer when we shall launch ourselves headlong into the conflagration at Ahn'Qiraj, {class}. But first we must gather our strength and prepare so that we can survive the onslaught of the insects and their masters.\n\nIf you are here again, then surely you wish to make another contribution of runecloth bandages to the war effort? Please do so as soon as you can and return to me once more.", completion = "It is a very selfless act of giving that you perform, {name}. One that is likely to save the lives of many combatants at Ahn'Qiraj. Thank you and know that you have the appreciation of the Horde for your donation. Should you create, or come across, more runecloth bandages, please consider bringing them to me here." }
quests[8611] = { id = 8611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs Lean Wolf Steaks!", description = "I'm not standing here just to get a nice tan, {class}. There are war preparations to be made. If we're going to crush those bugs at Ahn'Qiraj then we need to be ready, and that includes food too!\n\nThey have me gathering and salting lean wolf steaks here for the upcoming war. But since I need to stay here to take care of all of this, I need you to go out, kill some wolves and then cook up the meat into lean wolf steaks and bring them back to me here. You got all that?", sourceObjective = "Bring 20 Lean Wolf Steaks to Bloodguard Rawtar at the Valley of Spirits in Orgrimmar.", progress = "Back with those lean wolf steaks so soon, {class}? I don't care if they're overcooked or tartar, just make sure they're tasty and get them to me quick!", completion = "Ok, this stack of meat looks good to me. I'll salt them, and then pack them away and hopefully they'll keep fresh enough to be edible when the time comes.\n\nThanks for the contribution, {class}. Do you think you could bring me another rack?", sourceObjectiveStatus = "unverified-source-field" }
quests[8612] = { id = 8612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs More Lean Wolf Steaks!", progress = "As you can see, {class}, we still need to pack away more food for the soldiers. I don't know if you've ever been in a war before, but once you get past the initial shock of the battlefield, you can get pretty hungry.  You did a good job last time, so I expect that you'll do as well, if not a little quicker, in getting me another stack of those lean wolf steaks.", completion = "Smells like you, or someone you know, are quite the cook, {name}. Those lean wolf steaks are making my mouth water; I suppose a few going missing won't be noticed. Anyway, good work. I'll make sure someone packs them away right so that they don't spoil too much.\n\nIf you come across more, you know where to find me." }
quests[8613] = { id = 8613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs Spotted Yellowtail!", description = "It be a nice day for fishin', don't'cha think mon? Good thing, cuz I be needin' a lot of fish it lookin' like. The Horde, they askin' me to be in charge of collectin' a ton of the spotted yellowtail for them. They say they needin' it for the war they getting' ready for at Ahn'Qiraj. I say to them I do the best I can. So I be needin' to get some help. You gonna be helpin' me, {class}?", sourceObjective = "Bring 20 Spotted Yellowtail to Fisherman Lin'do at the Valley of Spirits in Orgrimmar.", progress = "Back so soon with the spotted yellowtail, {class}? You rememba' to cook it up nice? We not servin' raw fish to the soldiers out in the hot desert sun, to be sure.", completion = "Oh ya, this be the good stuff. I pack it up real nice so it not go to waste. Thanks be to you for helpin' me out like this. I'm thinkin' you an A-number-one fisherman for all this spotted yellowtail. An if you happen to fish up and cook even more, you bring it to me here; I make sure everyone know you did!", sourceObjectiveStatus = "unverified-source-field" }
quests[8614] = { id = 8614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs More Spotted Yellowtail!", progress = "So as you can see, we still be needin' a lot of the fishies. The combatants in the upcomin' Ahn'Qiraj War gonna be needin' a lot to eat, so I needin' to get all the spotted yellowtail that I can. You catch 'em, cook 'em, and bringin' 'em back to me here, and I be givin' you thanks, and the thanks of the Horde.", completion = "That be the best catch yet, {name}! Good, honest work right there. And no bones too! Thanks goin' out to you for this spotted yellowtail here mon. Come back soon if you cookin' up some more!" }
quests[8615] = { id = 8615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs Baked Salmon!", description = "The Ahn'Qiraj war effort is an immense undertaking, {class}. All of the materials being gathered here, whether it is metal for weapons, or food to eat, are all as important as the other. For, if you haven't eaten in days you will not have the strength to lift your axe when it matters.\n\nThus, we gather what food we can. I am collecting baked salmon, a dish that was chosen both for its sustenance and its ability to keep well. Can you aid me with this task, {class}?", sourceObjective = "Bring 20 Baked Salmon to Chief Sharpclaw at the Valley of Spirits in Orgrimmar.", progress = "Have you returned with the baked salmon, {class}? Remember, it must be cooked; I have no use for raw fish unfortunately.", completion = "Thank you for proving your interest in helping with the war effort here, {class}. Many would simply ignore our needs, opting instead to make a profit. But they do not have the gratitude of the Horde, as you now do. Their hearts are not full, as yours must be filled with the pride that comes from selfless giving.\n\nAgain, I thank you. Should you find the time to assist us further before our preparations are complete, I will be here waiting.", sourceObjectiveStatus = "unverified-source-field" }
quests[8616] = { id = 8616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs More Baked Salmon!", progress = "The last batch of baked salmon that you donated to the war effort looked very delicious, {class}. I must admit that I was tempted to take a few for myself. As you can tell, we have not yet reached our quota here. I am hoping you have returned because you have another stack of baked salmon with you.", completion = "Your donation of time and energy to the war effort goes above and beyond, {name}. I assure you that your labors have not gone unnoticed. You have my thanks, and the gratitude of the Horde. Please return to me again should you bake up another batch." }
quests[8617] = { id = 8617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs Singed Corestones!", description = "The time has come for you to contribute to the Ahn'Qiraj war effort, {class}. Gone are the halcyon days of whiling away your time in leisure. Now it is time to serve me and the Horde, and I assure you that I am not as forgiving as the Warchief.\n\nYou will gather your forces, a guild if you have one, and invade the Molten Core. Inside you will find that the denizens of the place have singed corestones. Bring these back to me in large quantities.", sourceObjective = "Bring 50 singed corestones to General Zog in Durotar.", sourceObjectiveStatus = "unverified-source-field" }
quests[8619] = { id = 8619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morndeep the Elder", sourceObjective = "It is good to know the people of this land still pay homage to the olden races.  I bid you well, {name}, and offer you this token...", sourceObjectiveStatus = "unverified-source-field" }
quests[8620] = { id = 8620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Only Prescription", description = "I should have known. My arch-enemy, Doctor Weavil, up to his old tricks! And now, thanks to your failure in Winterspring, Doctor Weavil has destroyed my book! How are you going to save the world now, hero?\n\nThe note I received stated that the only known copy of \"Draconic for Dummies: Volume II\" was ripped into 8 parts and scattered to the wind! If you somehow manage to find those missing chapters, use this magical binding to put them back together and return to me.", sourceObjective = "Recover the 8 lost chapters of Draconic for Dummies and combine them with the Magical Book Binding and return the completed book of Draconic for Dummies: Volume II to Narain Soothfancy in Tanaris.", progress = "I put my pants on just like you - one leg at a time. Except when my pants are on, I make arcanite buoys. Arcanite buoys, baby!", completion = "Fantastic! I can't believe you went through the hassle! Are you some kind of machine? If it were me, I would have probably just let the world implode.\n\nI tip my turban to you, sir. And no good deed should go unrewarded.", sourceObjectiveStatus = "unverified-source-field" }
quests[8621] = { id = 8621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormcaller's Footguards", description = "Qiraji magic is strong and ancient.  The most powerful qiraji wield items of such might, they'd give pause even to a dragon.\n\nBring me the qiraji bindings of dominance and other minor components and I'll create a set of powerful boots for you.\n\nYou will find them useful in the fight against the enemy.", sourceObjective = "Bring the Qiraji Bindings of Dominance, 2 Idols of the Sage, 5 Bronze Scarabs and 5 Clay Scarabs to Kandrostrasz in Ahn'Qiraj. This quest also requires Neutral faction with the Brood of Nozdormu.", progress = "You've acquired the items I requested, {name}?", completion = "You've done well, {name}.  You've proven you're no ordinary mortal.\n\nI give you these with the confidence they'll aid you in crushing the vile qiraji.", sourceObjectiveStatus = "unverified-source-field" }
quests[8622] = { id = 8622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormcaller's Hauberk", description = "The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj.  The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power.\n\nWhen the stars are favorable, he will lash out against all living beings with terrible wrath.  You must find him before then and find a way to bring his existence to an end.\n\nDo this and bring me a piece of his husk.  I shall grant you armor no mortal has ever worn... armor fit for one who has slain a god!", sourceObjective = "Bring the Carapace of the Old God, 2 Idols of the Sage, 5 Silver Scarabs and 5 Bone Scarabs to Vethsera inside Ahn'Qiraj. You must also attain Honored reputation with the Brood of Nozdormu to complete this quest.", progress = "At his dwelling in Ahn'Qiraj, dread C'Thun awaits in slumber.", completion = "I did not expect you to return from your attempt, {name}.\n\nYou've fulfilled a destiny greater than that of most immortal beings.\n\nBy slaying C'Thun you've not only saved all of Azeroth, you've also tipped the scales of cosmic events beyond your comprehension.\n\nAccept this breastplate as a symbol of the glory and burden that will come as a consequence of your actions.\n\nMay its power aid you in the challenges that await you, god-slayer!", sourceObjectiveStatus = "unverified-source-field" }
quests[8623] = { id = 8623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormcaller's Diadem", description = "The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity.  They mock me, knowing I cannot step further into their domain to save my brother Arygos.\n\nIn my visions I see their monstrous faces adorned by powerful crowns.  But I will have my revenge... I will transmute these symbols of Qiraji power to ones better suited to our needs.\n\nBring me the components I require, {name}.  I will give you a headpiece of unmatched power.", sourceObjective = "Bring Vek'lor's Diadem, 2 Idols of Rebirth, 5 Stone Scarabs and 5 Crystal Scarabs to Andorgos in Ahn'Qiraj. You must also attain Friendly reputation with the Brood of Nozdormu to complete this quest.", progress = "Did you bring me the components I asked for, {name}?", completion = "You've succeeded!  The whispers from the Twin Emperors have ceased.\n\nTake this as a reward.  The mere sight of it will strike fear in the hearts of the Qiraji... it shall remind them of their fallen leaders and of the mortal that slew them.", sourceObjectiveStatus = "unverified-source-field" }
quests[8624] = { id = 8624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormcaller's Leggings", description = "You seek to prove your worth to my kind, mortal?  Very well, perhaps we can be of mutual assistance.\n\nThe ancient sandworm, Ouro, is a being of legendary power.  He is rumored to have been created by the Old God himself as a mockery of life.\n\nHis skin is unnatural... thick, nearly impregnable, yet it's flexible and allows him to move with the speed and grace of a much smaller creature.\n\nBring me a sample of his skin along with other minor components and I shall craft you leggings of great power.", sourceObjective = "Bring the Skin of the Great Sandworm, 2 Idols of Strife, 5 Bronze Scarabs and 5 Ivory Scarabs to Kandrostrasz inside Ahn'Qiraj. You must also attain Friendly reputation with the Brood of Nozdormu to complete this quest.", progress = "Did you bring the components I require, {name}?", completion = "Yes... the worm's skin will make for an excellent protective layer.  Combined with the strongest parts from the Qiraji we've destroyed on our way here, this should make for a formidable piece of armor.  May it aid you in facing the unspeakable horrors that await inside!", sourceObjectiveStatus = "unverified-source-field" }
quests[8625] = { id = 8625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enigma Shoulderpads", description = "It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon.\n\nBring me the bindings worn by the highest Qiraji leaders and I shall shape them into a set of pauldrons more dreadful than even the wings of Nefarian himself!", sourceObjective = "Bring the Qiraji Bindings of Dominance, 2 Idols of Death, 5 Stone Scarabs and 5 Bronze Scarabs to Andorgos in Ahn'Qiraj. You must also attain Neutral reputation with the Brood of Nozdormu to complete this quest.", progress = "Have you collected the components I require?", completion = "From the materials you bring and from the scales of our fallen Qiraji foes I make you these pauldrons, mortal.  May they grant you the protection you need and may the sight of them strike fear into our enemies.", sourceObjectiveStatus = "unverified-source-field" }
quests[8626] = { id = 8626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Striker's Footguards", description = "Qiraji magic is strong and ancient.  The most powerful qiraji wield items of such might, they'd give pause even to a dragon.\n\nBring me the qiraji bindings of command and other minor components by and I'll create a set of powerful boots for you.\n\nYou will find them useful in the fight against the enemy.", sourceObjective = "Bring the Qiraji Bindings of Command, 2 Idols of Life, 5 Stone Scarabs and 5 Bone Scarabs to Kandrostrasz in Ahn'Qiraj. This quest also requires Neutral faction with the Brood of Nozdormu.", progress = "You've acquired the items I requested, {name}?", completion = "You've done well, {name}.  You've proven you're no ordinary mortal.\n\nI give you these with the confidence they'll aid you in crushing the vile qiraji.", sourceObjectiveStatus = "unverified-source-field" }
