quests[8686] = { id = 8686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "High Mountain the Elder", sourceObjective = "Your spirit burns with life, young {class}.  I accept the homage you pay, and offer in return this token...", sourceObjectiveStatus = "unverified-source-field" }
quests[8687] = { id = 8687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Target: Hive'Zora Tunnelers", description = "Reinforcements have been called on to join the assault on Hive'Zora.  You have been selected to target Hive'Zora tunnelers.  Report back to Commander Mar'alith after completing your task.", sourceObjective = "Slay 30 Hive'Zora Tunnelers and report back to Commander Mar'alith at Cenarion Hold in Silithus. You must also bring Combat Task Briefing VII in order to complete this quest.", progress = "You have something to tell me, {class}?", completion = "Excellent work, {name}.  Without their tunnelers, the silithid will have a hard time repairing any damage inflicted to their hive's structure.  I assume you'll want a new task.", sourceObjectiveStatus = "unverified-source-field" }
quests[8688] = { id = 8688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windrun the Elder", sourceObjective = "The heavens, in their countless stars, hold answers to earthly mysteries, {name}.  Might, then, the wise, and the lucky, gaze up and find truth?", sourceObjectiveStatus = "unverified-source-field" }
quests[8689] = { id = 8689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shroud of Infinite Wisdom", description = "I'm glad to hear you're aiding us in our attack on Ahn'Qiraj, {name}.  I can make you a protective item that'll be of assistance in the fight against our enemy, {class}.\n\nI shall need a Qiraji drape, which I'll resize for you of course.  I'll also need idols and scarabs which I'll use to create a suitable clasp.\n\nI promise you won't be disappointed.", sourceObjective = "Bring 1 Qiraji Martial Drape, 2 Jasper Idols, 5 Gold Scarabs and 5 Clay Scarabs to Keyl Swiftclaw in Silithus. You must also obtain Revered reputation with Cenarion Circle to complete this quest.", progress = "Did you bring the materials for the cloak, {name}?", completion = "Ah yes... this drape is immaculate.\n\nTake this cloak, {name}.  May it protect you from the foul magic of the Qiraji.", sourceObjectiveStatus = "unverified-source-field" }
quests[8690] = { id = 8690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cloak of the Gathering Storm", description = "I'm glad to hear you're aiding us in our attack on Ahn'Qiraj, {name}.  I can make you a protective item that'll be of assistance in the fight against our enemy, {class}.\n\nI shall need a Qiraji drape, which I'll resize for you of course.  I'll also need idols and scarabs which I'll use to create a suitable clasp.\n\nI promise you won't be disappointed.", sourceObjective = "Bring 1 Qiraji Regal Drape, 2 Obsidian Idols, 5 Clay Scarabs and 5 Gold Scarabs to Keyl Swiftclaw in Silithus. You must also obtain Revered reputation with Cenarion Circle to complete this quest.", progress = "Did you bring the materials for the cloak, {name}?", completion = "Ah yes... this drape is immaculate.\n\nTake this cloak, {name}.  May it protect you from the foul magic of the Qiraji.", sourceObjectiveStatus = "unverified-source-field" }
